// ================= Aprender: módulo «produtos» =================
// Aulas completas. Regras de Portugal só com fonte oficial (campo `src`, verificado em 17/11/2026); o que não ficou confirmado leva `pending:true` («Por confirmar»).
// Contas dos exemplos feitas aqui (prefixo _prod_), para o texto nunca divergir do número certo.

const _prod_n=(n,d=2)=>Number(n).toLocaleString('pt-PT',{minimumFractionDigits:d,maximumFractionDigits:d});
const _prod_pc=(n,d=1)=>_prod_n(n,d)+'%';
// Preço de uma obrigação de valor nominal 100, cupão anual cpn (em % do nominal), yield y (decimal), n anos
const _prod_bp=(cpn,y,n)=>{ let p=0; for(let t=1;t<=n;t++) p+=cpn/Math.pow(1+y,t); return p+100/Math.pow(1+y,n); };
// Duração de Macaulay (em anos) e modificada
const _prod_dur=(cpn,y,n)=>{ let s=0,p=0; for(let t=1;t<=n;t++){ const pv=(cpn+(t===n?100:0))/Math.pow(1+y,t); p+=pv; s+=t*pv; } return s/p; };
const _prod_mod=(cpn,y,n)=>_prod_dur(cpn,y,n)/(1+y);
// Yield até à maturidade (em %) por bissecção, para preço p, cupão cpn (%) e n anos
const _prod_ytm=(p,cpn,n)=>{ let lo=0,hi=.5; for(let i=0;i<80;i++){ const m=(lo+hi)/2; if(_prod_bp(cpn,m,n)>p) lo=m; else hi=m; } return (lo+hi)/2*100; };
// Capital final de um depósito com juros reinvestidos, líquidos de 28% de imposto sobre o juro de cada ano
const _prod_dep=(cap,r,anos)=>cap*Math.pow(1+r*0.72,anos);
const _prod_ref={l:'Portal das Finanças: Tributação de produtos financeiros em sede de IRS (edição de outubro de 2023)',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/Guias/Documents/Guia_Fiscal_produtos_financeiros.pdf'};
const _prod_fgd={l:'FGD: perguntas frequentes',u:'https://www.fgd.pt/en/faqs'};
const _prod_ebf21={l:'Portal das Finanças: Estatuto dos Benefícios Fiscais, artigo 21.º',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/bf_rep/Pages/ebf-artigo-21-ordm-.aspx'};

LRN.push(
{ id:'depositos', topic:'produtos', o:1, title:'Depósitos a prazo', mins:7,
  lead:'O produto mais simples que existe: entregas dinheiro ao banco por um prazo e ele paga-te juros. O risco é baixo, mas o que fica no bolso depois de impostos e de inflação é muito menos do que a taxa anunciada.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Imagina que emprestas a bicicleta a um vizinho durante um ano e ele te paga uma pequena renda por isso. No fim, devolve-ta como estava. Um <b>depósito a prazo</b> é isto, só que o vizinho é o banco e a bicicleta é o teu dinheiro. O banco usa o dinheiro para conceder crédito a outras pessoas, cobra-lhes mais do que te paga a ti, e a diferença é o negócio dele.'},
    {t:'p',id:'p1',x:'Tu escolhes o <b>montante</b> e o <b>prazo</b> (3 meses, 1 ano, 5 anos...). A taxa fica normalmente fixada à partida e, em troca de deixares o dinheiro parado, o banco paga mais do que numa conta à ordem, que é a conta onde tens o dinheiro disponível todos os dias. Mobilizar o depósito antes do fim (ir buscar o dinheiro mais cedo) pode implicar perder parte ou a totalidade dos juros, conforme o contrato.'},
    {t:'h',id:'h1',x:'O que tens de ler antes de assinar'},
    {t:'p',id:'p2',x:'Os bancos anunciam a <b>taxa anual nominal bruta (TANB)</b>: o juro por ano antes de impostos. O que importa para ti é a taxa depois do imposto, a taxa líquida. Há mais três pontos que mudam o resultado e que muita gente só descobre depois.'},
    {t:'ul',id:'u1',x:[
      '<b>Quando se pagam os juros.</b> Podem ser pagos todos os meses, todos os trimestres ou só no fim. Se forem pagos durante o prazo e os deixares parados na conta à ordem, não rendem; se os reinvestires, rendem juros sobre juros.',
      '<b>Renovação automática.</b> Muitos depósitos renovam sozinhos no vencimento, a uma taxa que pode ser bem pior do que a inicial. Vê a data e o que o contrato diz.',
      '<b>Mobilização antecipada.</b> Alguns depósitos não permitem retirar antes do prazo; outros permitem com penalização. O dinheiro que pode ser preciso para uma emergência não deve ficar num depósito rígido.']},
    {t:'p',id:'p3',x:'Dois pontos fazem do depósito um produto seguro: o capital não oscila e, nos bancos a operar em Portugal, está coberto pelo <b>Fundo de Garantia de Depósitos até 100 000 € por depositante e por banco</b> (o limite soma todas as tuas contas nesse banco, incluindo depósitos a prazo). Por isso quem tem mais do que isso costuma espalhar o dinheiro por mais do que uma instituição.'},
    {t:'w',id:'wf',w:'fgd'},
    {t:'h',id:'h2',x:'O imposto sobre os juros'},
    {t:'p',id:'p4',x:'Os juros de depósitos de um residente em Portugal estão sujeitos a <b>retenção na fonte de 28%</b>, a título definitivo (taxa liberatória, art. 71.º do Código do IRS). O banco desconta o imposto e entrega-te o juro líquido, por isso, em regra, não tens de os declarar no Modelo 3. Podes optar por englobar os juros no IRS, mas, segundo a AT, isso só compensa a quem tem rendimentos num escalão com taxa inferior a 28%. Se abrires uma conta num banco no estrangeiro, os juros têm de ser declarados no anexo J e são tributados à taxa de 28% (a AT indica o quadro 8A, código E21). Verificado em 17/11/2026.'},
    {t:'w',id:'w1',w:'calc',c:'netint'},
    {t:'note',id:'n1',x:'A taxa que o banco anuncia é a bruta. Compara depósitos pela taxa e pelo prazo, mas lembra-te de que o que recebes é o valor líquido de imposto e que a inflação também conta.'},
    {t:'h',id:'h3',x:'Um exemplo a cinco anos'},
    {t:'p',id:'p5',x:`Pões ${_e(10000)} num depósito a 5 anos com taxa bruta de 3% e reinvestes os juros todos os anos. Depois do imposto, cada ano rende 3% × 72% = ${_prod_pc(3*0.72,2)}. Ao fim de 5 anos tens ${_e(_prod_dep(10000,0.03,5))}. Parece bem, mas se os preços subirem 2% ao ano, esse dinheiro compra o equivalente a ${_e(_prod_dep(10000,0.03,5)/Math.pow(1.02,5))} de hoje. O ganho real é de apenas ${_e(_prod_dep(10000,0.03,5)/Math.pow(1.02,5)-10000)} em 5 anos.`},
    {t:'stat',id:'s1',v:Math.round(_prod_dep(10000,0.03,5)/Math.pow(1.02,5)),label:'o que 10 000 € a 3% bruta, 5 anos, valem em poder de compra de hoje (inflação de 2%, valor de exemplo)'},
    {t:'note',id:'n2',x:'Isto não quer dizer que o depósito seja mau. Quer dizer que serve para o que é: guardar dinheiro de que vais precisar a curto prazo, sem risco, e não para fazer crescer património durante décadas.'},
    {t:'h',id:'h4',x:'Prazos longos e a regra dos cinco anos'},
    {t:'p',id:'p6',x:`A AT indica que os depósitos podem beneficiar do regime do art. 20.º-A do Estatuto dos Benefícios Fiscais, se o capital ficar imobilizado pelo menos 5 anos e os juros só vencerem no fim do período contratado. Nesse caso só 4/5 do rendimento é tributado se o reembolso ocorrer entre os 5 e os 8 anos, e só 2/5 se ocorrer depois dos 8 anos. Na prática, a taxa efetiva fica em ${_prod_pc(28*4/5)} e ${_prod_pc(28*2/5)} do juro, respetivamente.`},
    {t:'note',id:'n3',pending:true,x:'Nem todos os bancos oferecem depósitos que cumpram as condições do art. 20.º-A. Pergunta ao banco se o produto concreto está abrangido antes de contares com esta redução.'},
    {t:'h',id:'h5',x:'Um caso real: quando a taxa foi quase zero'},
    {t:'p',id:'p7',x:'Depois da crise financeira de 2008 e da crise da dívida na Zona Euro, o Banco Central Europeu baixou as taxas de juro até perto de zero e depois, durante alguns anos, até valores negativos. Os depósitos pagavam muito pouco e, com inflação positiva, quem tinha as poupanças só em depósitos perdia poder de compra todos os anos. Foi nessa altura que muita gente começou a olhar para outros produtos. Quando as taxas voltaram a subir, a partir de 2022, os depósitos passaram a pagar mais. A lição é que a taxa do depósito não é uma propriedade do produto: acompanha o ciclo das taxas de juro do banco central.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Comparar taxas brutas com taxas líquidas, ou taxas de prazos diferentes, como se fossem iguais.',
      'Deixar o depósito renovar sozinho sem ver a nova taxa.',
      'Pôr no mesmo banco mais de 100 000 € e achar que está tudo coberto.',
      'Usar o depósito a prazo para o dinheiro de emergência e depois pagar penalização para o levantar.',
      'Achar que «sem risco» quer dizer «sem custo»: a inflação é um custo silencioso.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p8',x:'Em Portugal os depósitos são oferecidos por todos os bancos e por algumas instituições digitais. Os que operam cá estão cobertos pelo Fundo de Garantia de Depósitos até 100 000 € por depositante e por banco. Para saber como os juros entram na declaração e o que muda com o englobamento, vê os temas <b>Dividendos e juros</b> e <b>Englobamento: quando compensa</b> no módulo de impostos; para saber o que acontece se o banco falir, o tema <b>Quem protege o teu dinheiro se o banco falir</b>; e para comparar com os produtos do Estado, o tema <b>Certificados de Aforro e do Tesouro</b>.'},
    {t:'note',id:'n4',pending:true,x:'Para depósitos num banco de outro país da UE, a garantia é dada pelo sistema desse país. Confirma o limite e as condições no site do banco antes de depositares.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Um depósito a prazo é um empréstimo ao banco: capital estável, juros previstos à partida.',
      'O Fundo de Garantia de Depósitos protege até 100 000 € por depositante e por banco.',
      'Os juros pagam 28% de retenção na fonte; o que recebes é a taxa líquida, não a bruta.',
      'A inflação pode comer quase todo o ganho real: o depósito serve a curto prazo, não para fazer crescer o património.',
      'Lê o contrato: pagamento de juros, renovação automática e mobilização antecipada.']},
    {t:'fazve',id:'q1',ensina:['p4','w1'],q:'Aplicas 10 000 € num depósito a 2,5% de taxa bruta anual. Quanto recebes de juro líquido ao fim de um ano?',unit:'€',answer:_c('netint',{cap:10000,tax:2.5})[2],tol:.01,why:'Juro bruto: 250 €. Retenção de 28%: 70 €. Líquido: 180 €.'},
    {t:'fazve',id:'q2',ensina:['p4','p5'],q:'Um depósito tem taxa bruta de 3%. Qual é a taxa líquida anual, em %, depois dos 28% de retenção?',unit:'%',answer:Number((3*0.72).toFixed(2)),tol:.02,why:'Fica com 72% do juro: 3% × 0,72 = 2,16%. Se a inflação for de 2%, o ganho real é minúsculo.'},
    {t:'decide',id:'q3',ensina:['p3','wf'],label:'Decide',q:'Tens 90 000 € no banco A e 90 000 € no banco B, ambos a operar em Portugal. Quanto está coberto pelo Fundo de Garantia de Depósitos?',o:['100 000 € no total','90 000 € no banco A mais 100 000 € no banco B','180 000 €, porque cada banco cobre até 100 000 € e nenhum ultrapassa esse valor'],c:2,why:'O limite é de 100 000 € por depositante e por instituição. Como em cada banco só tens 90 000 €, estás coberto nos dois: 180 000 € no total.'},
    {t:'erro',id:'q4',ensina:['p2','p4','u1'],label:'Encontra o erro',q:'Uma destas frases sobre depósitos a prazo está errada. Qual?',o:['A taxa anunciada é normalmente a bruta, antes de impostos','Os juros sofrem retenção na fonte de 28%, em regra a título definitivo','Um depósito a prazo pode sempre ser levantado a qualquer momento sem perder nada','A renovação automática pode ser feita a uma taxa diferente da inicial'],c:2,why:'Muitos depósitos penalizam, ou nem permitem, a mobilização antes do prazo. Depende do contrato.'}
  ], src:[{l:'Portal das Finanças: artigo 71.º do Código do IRS (taxas liberatórias)',u:'https://info.portaldasfinancas.gov.pt/pt/informacao_fiscal/codigos_tributarios/cirs_rep/Pages/irs71.aspx'},_prod_ref,_prod_fgd] },

{ id:'certificados', topic:'produtos', o:2, title:'Certificados de Aforro e do Tesouro', mins:7,
  lead:'Produtos de poupança emitidos pela República Portuguesa, subscritos por pessoas singulares. O Estado é quem paga, o que os torna dos produtos mais seguros ao teu alcance. As regras são específicas e mudam de série para série.',
  blocks:[
    {t:'h',id:'h0',x:'Quem está do outro lado'},
    {t:'p',id:'p0',x:'Num depósito emprestas ao banco; nos certificados emprestas diretamente ao Estado português. A entidade que gere a dívida pública, o <b>IGCP</b>, emite estes produtos para financiar o Estado com a poupança das famílias. Por isso o risco que corres é o de a República falhar o pagamento, que é considerado muito baixo. O Fundo de Garantia de Depósitos não se aplica, porque isto não é um depósito: a garantia é o próprio Estado.'},
    {t:'p',id:'p1',x:'Os <b>Certificados de Aforro</b> existem em várias séries; a mais recente é a <b>Série F</b>. Os <b>Certificados do Tesouro</b> têm regras próprias, com taxas pré-definidas e crescentes. Em ambos só podem subscrever pessoas singulares: nem empresas nem associações.'},
    {t:'h',id:'h1',x:'Duas séries lado a lado'},
    {t:'cmp',id:'c1',head:['','Certificados de Aforro, Série F','Certificados do Tesouro, Série 5'],rows:[
      ['Prazo','15 anos','10 anos'],
      ['Juro','Taxa base ligada à Euribor a 3 meses (entre 0% e 2,5%) mais um prémio que sobe com o tempo','Taxas crescentes ao longo dos anos, definidas à partida'],
      ['Capitalização','Juros capitalizados trimestralmente, líquidos de IRS','Ver a ficha técnica do IGCP'],
      ['Resgate antecipado','A partir de 3 meses após a subscrição; resgatar a meio de um trimestre perde os juros desse trimestre','Ver a ficha técnica do IGCP'],
      ['Onde subscrever','AforroNet, CTT ou Espaço Cidadão','Ver a ficha técnica do IGCP']],
      cap:'Fonte: fichas técnicas do IGCP, verificadas em 17/11/2026. Verifica sempre as condições da série em vigor antes de subscrever.'},
    {t:'h',id:'h2',x:'Como funciona a taxa da Série F'},
    {t:'p',id:'p2',x:'A taxa de cada trimestre tem duas partes. A <b>taxa base</b> acompanha a <b>Euribor a 3 meses</b>, que é a taxa a que os bancos europeus se emprestam dinheiro entre si por três meses. Se a Euribor for negativa, a base é 0%; se for muito alta, a base fica no teto de 2,5%. Depois soma-se o <b>prémio de permanência</b>, que recompensa quem deixa o dinheiro ficar: 0,25 pontos percentuais do 2.º ao 5.º ano, subindo até 1,75 pontos percentuais nos dois últimos anos.'},
    {t:'p',id:'p3',x:`Um exemplo com os extremos, sem impostos e só para perceber a escala: sobre ${_e(10000)}, um prémio de 0,25 pontos vale ${_e(10000*0.0025)} por ano; um prémio de 1,75 pontos vale ${_e(10000*0.0175)} por ano. No melhor caso possível, nos dois últimos anos, base no teto (2,5%) mais prémio máximo (1,75 pontos) dá ${_prod_pc(2.5+1.75,2)}. Na prática a taxa base muda de trimestre para trimestre, por isso o rendimento total não se sabe de antemão.`},
    {t:'note',id:'n1',pending:true,x:'Os limites máximos de subscrição e as taxas exatas das séries atuais aparecem de forma diferente em fontes diferentes. Confirma no AforroNet / IGCP antes de decidir. O mesmo vale para as condições de resgate e capitalização dos Certificados do Tesouro Série 5.'},
    {t:'h',id:'h3',x:'A regra que apanha muita gente: o trimestre'},
    {t:'p',id:'p4',x:'Os juros são capitalizados todos os trimestres, e se resgatares a meio de um trimestre perdes os juros desse trimestre. Por isso, quem precisa do dinheiro faz bem em resgatar logo no início do trimestre seguinte, em vez de o fazer um dia antes de o trimestre acabar. Também há um período inicial de 3 meses em que o dinheiro não pode ser levantado, o que obriga a ter um fundo de emergência separado, num sítio de acesso imediato.'},
    {t:'h',id:'h3b',x:'Certificados ou depósito: como escolher'},
    {t:'p',id:'p4b',x:'Não há um vencedor universal. Depende do que valorizas mais: previsibilidade ou flexibilidade, taxa fixa ou taxa que acompanha as taxas do mercado, garantia do banco ou garantia do Estado. O que podes fazer é comparar as características que não mudam.'},
    {t:'cmp',id:'c3',head:['','Depósito a prazo','Certificados de Aforro, Série F'],rows:[
      ['Quem garante','O banco, com Fundo de Garantia de Depósitos até 100 000 €','O Estado português'],
      ['Taxa','Normalmente fixa à partida','Variável: base ligada à Euribor mais prémio de permanência'],
      ['Prazo','O que escolheres','15 anos, com resgate possível a partir de 3 meses'],
      ['Quem pode comprar','Pessoas e empresas','Só pessoas singulares'],
      ['Onde','No banco','AforroNet, CTT, Espaço Cidadão']],
      cap:'Dados do IGCP e do FGD, verificados em 17/11/2026.'},
    {t:'p',id:'p4c',x:'Uma regra simples: o que precisas de ter à mão em menos de 3 meses não devia estar em certificados. Para a segunda camada da reserva de emergência, o dinheiro que só usarias numa situação séria, os certificados podem fazer sentido, e a ideia de camadas está explicada no tema <b>Fundo de emergência: a rede por baixo de tudo</b>.'},
    {t:'h',id:'h4',x:'Um cenário real: anos de Euribor negativa'},
    {t:'p',id:'p5',x:'Durante vários anos, depois da crise da dívida na Zona Euro, a Euribor a 3 meses esteve abaixo de zero. Com uma taxa base que nunca desce de 0%, nesses anos o rendimento de uma série como a F viria só do prémio de permanência, e quem acabava de subscrever não tinha prémio nenhum. Já quando a Euribor sobe acima de 2,5%, é o teto que trava o ganho. A lição é a de sempre: um produto seguro não protege automaticamente da inflação, e o piso, o teto e o prazo da série contam tanto como a segurança.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Pôr o fundo de emergência em certificados, e descobrir que não pode ser levantado nos primeiros 3 meses ou que perde os juros do trimestre em curso.',
      'Comparar a taxa dos certificados com a taxa bruta de um depósito sem ver o que é líquido e como se capitalizam os juros.',
      'Achar que a taxa está garantida durante 15 anos: só o prémio está definido à partida; a base muda.',
      'Subscrever através de intermediários que não são o IGCP/AforroNet/CTT/Espaço Cidadão.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Estes são produtos exclusivamente portugueses, por isso não há dúvida de acesso: subscrevem-se online no AforroNet ou presencialmente nos CTT e nos Espaços Cidadão, e só por pessoas singulares. Para comparar com um depósito, vê o tema <b>Depósitos a prazo</b> neste módulo e o tema <b>Dividendos e juros</b> no módulo de impostos.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Emprestas ao Estado português através do IGCP; o risco de falha é considerado muito baixo.',
      'Os Certificados de Aforro Série F duram 15 anos, com taxa base ligada à Euribor a 3 meses (0% a 2,5%) mais um prémio de permanência crescente.',
      'Resgate possível depois de 3 meses; resgatar a meio de um trimestre perde os juros desse trimestre.',
      'Só pessoas singulares, e o fundo de garantia de depósitos não se aplica: a garantia é o Estado.',
      'A taxa não é fixa: confirma sempre as condições da série em vigor.']},
    {t:'decide',id:'q1',ensina:['c1','p4'],label:'Decide',q:'Subscreveste Certificados de Aforro Série F há 2 meses e precisas do dinheiro. Podes resgatá-los?',o:['Ainda não: o resgate só é possível a partir de 3 meses após a subscrição','Sim, a qualquer momento sem perder nada','Nunca, só ao fim de 15 anos'],c:0,why:'O resgate antecipado é possível a partir de três meses após a subscrição. Antes disso o dinheiro está bloqueado.'},
    {t:'erro',id:'q2',ensina:['p1','c1'],label:'Encontra o erro',q:'Uma destas afirmações sobre os Certificados de Aforro Série F está errada. Qual?',o:['São emitidos pelo Estado, através do IGCP','Só pessoas singulares os podem subscrever','Têm prazo de 5 anos','Os juros são capitalizados trimestralmente'],c:2,why:'O prazo da Série F é de 15 anos, não 5.'},
    {t:'fazve',id:'q3',ensina:['p3'],q:'Sem contar impostos, quanto vale por ano o prémio máximo de 1,75 pontos percentuais sobre 10 000 € de certificados?',unit:'€',answer:Math.round(10000*0.0175),tol:.01,why:'1,75% de 10 000 € são 175 €. É um valor de exemplo para perceber a escala do prémio.'},
    {t:'decide',id:'q4',ensina:['p2','p4'],label:'Decide',q:'Faltam 3 dias para acabar o trimestre e queres resgatar Certificados de Aforro Série F que já tens há anos. O que é mais vantajoso, se não tiveres urgência?',o:['Resgatar já, para não perder tempo','Esperar pelo trimestre seguinte, para não perder os juros do trimestre em curso','Tanto faz, os juros são pagos ao dia'],c:1,why:'Quem resgata a meio de um trimestre perde os juros desse trimestre. Esperar três dias evita essa perda.'}
  ], src:[{l:'IGCP: ficha técnica dos Certificados de Aforro, Série F',u:'https://www.igcp.pt/en/aforristas/produtos-de-aforro/certificados-de-aforro/ficha-tecnica-certificados-de-aforro-serie-f'},{l:'IGCP: Certificados do Tesouro «Série 5»',u:'https://www.igcp.pt/pt/noticias/igcp-lanca-certificados-do-tesouro-serie-5-com-taxas-crescentes-e-capital-garantido'}] }
);
LRN.push(
{ id:'mercado-monetario', topic:'produtos', o:3, title:'Fundos do mercado monetário', mins:6,
  lead:'Um fundo monetário aplica o dinheiro em dívida de prazo muito curto e, por isso, o seu valor quase não oscila. Serve para guardar dinheiro parado a render algo, mas não é um depósito e não tem garantia nenhuma.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Pensa numa sala de espera de aeroporto. As pessoas entram e saem o tempo todo, ninguém fica lá muito tempo, e a sala nunca se enche demais. Um <b>fundo do mercado monetário</b> funciona assim: junta o dinheiro de muitos investidores e empresta-o por prazos curtíssimos (dias, semanas ou poucos meses) a Estados, bancos e grandes empresas. Quando um empréstimo vence, o fundo empresta de novo, à taxa que estiver em vigor nesse dia.'},
    {t:'p',id:'p1',x:'O resultado é um produto com duas características que quase nunca andam juntas: valor muito estável e rendimento que acompanha as taxas do banco central. Quando o BCE sobe as taxas, o fundo passa a receber mais quase de imediato; quando as desce, o rendimento cai em semanas.'},
    {t:'h',id:'h1',x:'Como funciona por dentro'},
    {t:'p',id:'p2',x:'O fundo compra instrumentos como <b>bilhetes do Tesouro</b> (dívida de curto prazo do Estado), <b>papel comercial</b> (dívida de curto prazo de empresas), depósitos bancários e outros empréstimos de curto prazo. Em vez de pagar cupões, muitos destes instrumentos são comprados abaixo do valor que vão pagar no vencimento, e a diferença é o rendimento. O valor do fundo vai subindo um pouco todos os dias, à medida que esses instrumentos se aproximam do vencimento.'},
    {t:'p',id:'p3',x:'Porque é que o valor quase não oscila? Porque o prazo é curto. Um empréstimo que vence em 60 dias só tem dois meses para ser afetado por uma subida das taxas; um que vence em 10 anos tem uma década. Esta sensibilidade chama-se <b>duração</b> e vê-se melhor com números.'},
    {t:'cmp',id:'c1',head:['Instrumento','Prazo','Aproximadamente, se as taxas subirem 1 ponto percentual'],rows:[
      ['Bilhete do Tesouro a 2 meses',`${_prod_n(2/12,2)} anos`,`perde cerca de ${_prod_pc(2/12)}`],
      ['Obrigação a 5 anos (cupão 3%)','5 anos',`perde cerca de ${_prod_pc(_prod_mod(3,0.03,5))}`],
      ['Obrigação a 10 anos (cupão 3%)','10 anos',`perde cerca de ${_prod_pc(_prod_mod(3,0.03,10))}`]],
      cap:'Valores de exemplo, calculados com a duração modificada. O bilhete a 2 meses é de cupão zero, por isso a duração é igual ao prazo.'},
    {t:'h',id:'h2',x:'Fundo monetário, depósito e conta à ordem lado a lado'},
    {t:'cmp',id:'c2',head:['','Depósito a prazo','Fundo monetário','Conta à ordem'],rows:[
      ['Garantia','Fundo de Garantia de Depósitos até 100 000 € por banco','Nenhuma: o valor pode, em casos raros, descer','Fundo de Garantia de Depósitos'],
      ['Acesso ao dinheiro','Só no fim do prazo, ou com penalização','Resgate em poucos dias úteis, em regra','Imediato'],
      ['Rendimento','Taxa fixa à partida','Acompanha as taxas do banco central','Quase nulo'],
      ['Custos','Nenhuns diretos','Comissão de gestão (TER), tipicamente baixa','Comissões da conta'],
      ['Imposto','28% sobre o juro','28% sobre o ganho, segundo o guia da AT','Idem']],
      cap:'O imposto dos fundos segue o guia fiscal da AT: 28% sobre o resgate. Confirma o caso concreto do teu fundo.'},
    {t:'h',id:'h3',x:'Um exemplo com custos e imposto'},
    {t:'p',id:'p4',x:`Imagina que o fundo rende 2,5% por ano e cobra 0,2% de custos (valores de exemplo). Com ${_e(10000)} aplicados durante um ano, o ganho antes de custos é ${_e(10000*0.025)}; os custos levam ${_e(10000*0.002)}; sobra ${_e(10000*0.023)}. Ao resgatar, o imposto de 28% leva ${_e(10000*0.023*0.28)} e ficas com ${_e(10000*0.023*0.72)} de ganho líquido. Um depósito a 2,5% bruta daria ${_e(10000*0.025*0.72)} líquidos. A diferença está nos custos: o fundo só compensa se te der mais flexibilidade, ou uma taxa melhor do que a do depósito que estás a comparar.`},
    {t:'h',id:'h4',x:'Quando a sala de espera se enche: 2008 e 2020'},
    {t:'p',id:'p5',x:'Em setembro de 2008, depois da falência do banco Lehman Brothers, um fundo monetário americano de grande dimensão que tinha comprado dívida da Lehman viu o valor de cada unidade cair abaixo de 1 dólar, algo que se julgava quase impossível. Os investidores correram a resgatar noutros fundos semelhantes e as autoridades tiveram de intervir. Em março de 2020, no início da pandemia, houve nova tensão e os bancos centrais voltaram a atuar. Os fundos monetários são seguros em tempos normais, mas não são um depósito: o risco existe, só é muito pequeno.'},
    {t:'note',id:'n1',pending:true,x:'Na União Europeia os fundos monetários são regulados por um regulamento próprio da UE (Regulamento (UE) 2017/1131), que define tipos de fundo (de valor variável, de valor constante de dívida pública e de baixa volatilidade) e limites de prazo e liquidez. Não foi possível confirmar os detalhes do texto oficial nesta consulta, por isso não escrevemos aqui os números exatos. Lê o prospeto e o documento de informação fundamental (KID) do fundo concreto.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Achar que «monetário» quer dizer «garantido». Não é um depósito e o Fundo de Garantia de Depósitos não se aplica.',
      'Comparar a taxa do fundo com a do depósito sem descontar custos e imposto.',
      'Esquecer que o rendimento muda quando o banco central muda as taxas: o que rendia 3% pode passar a render 1%.',
      'Usar fundos monetários de moeda diferente do euro sem pensar no risco cambial.',
      'Comprar produtos chamados «dinâmicos» ou «de rendimento» que, afinal, têm risco de crédito muito acima do de um monetário a sério.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Em Portugal podes aceder a fundos monetários através de gestoras e bancos nacionais e, em corretoras, a fundos e ETFs UCITS em euros. Alguns ETFs replicam a taxa de curto prazo do euro (a €STR), que é a taxa overnight publicada pelo BCE. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), o resgate de unidades de participação em fundos mobiliários residentes sofre retenção de 28%, a título definitivo; nos fundos não residentes (por exemplo irlandeses ou luxemburgueses), as distribuições e os ganhos no resgate são tributados a 28%, e tens de os declarar no anexo J. Vê o tema <b>Mais-valias: quanto imposto pagas ao vender</b> e o tema <b>ETFs de acumulação e de distribuição</b>.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Um fundo monetário empresta por prazos curtíssimos, por isso o valor quase não oscila.',
      'O rendimento acompanha as taxas do banco central: sobe e desce com elas.',
      'Não é um depósito: não tem garantia de capital nem Fundo de Garantia de Depósitos.',
      'Os custos pesam: compara sempre o rendimento líquido de custos e de imposto.',
      'Serve para guardar dinheiro a curto prazo, não para crescer património.']},
    {t:'decide',id:'q1',ensina:['p3','c1'],label:'Decide',q:'As taxas de juro sobem 1 ponto percentual. Qual destes produtos perde mais valor?',o:['Um fundo monetário','Um bilhete do Tesouro a 2 meses','Uma obrigação a 10 anos com cupão fixo'],c:2,why:'Quanto maior o prazo, maior a duração e mais o preço desce quando as taxas sobem. Um instrumento a 2 meses quase não é afetado.'},
    {t:'fazve',id:'q2',ensina:['p4'],q:'Um fundo monetário rende 2,5% brutos por ano e cobra 0,2% de custos. Aplicas 10 000 € durante um ano e resgatas. Qual é o ganho líquido depois do imposto de 28%, em euros?',unit:'€',answer:10000*0.023*0.72,tol:.02,why:'Ganho antes de custos: 250 €. Custos: 20 €. Sobram 230 €. Imposto de 28%: 64,40 €. Ganho líquido: 165,60 €.'},
    {t:'decide',id:'q3',ensina:['c2'],label:'Decide',q:'Tens 20 000 € num fundo monetário e o banco onde tens a conta fecha. O Fundo de Garantia de Depósitos cobre esse dinheiro?',o:['Não: um fundo monetário não é um depósito','Sim, até 100 000 €','Só metade'],c:0,why:'O Fundo de Garantia de Depósitos cobre depósitos. As unidades de participação de um fundo não são depósitos e o fundo é uma entidade separada do banco que o comercializa.'},
    {t:'erro',id:'q4',ensina:['p1','p5','c2'],label:'Encontra o erro',q:'Uma destas frases sobre fundos monetários está errada. Qual?',o:['O rendimento acompanha as taxas do banco central','O valor da unidade quase não oscila em tempos normais','O capital está sempre garantido','Os custos reduzem o rendimento que recebes'],c:2,why:'Não há capital garantido. Em 2008 houve um fundo monetário que perdeu valor, e em 2020 houve tensão de liquidez.'}
  ], src:[_prod_ref,_prod_fgd] },

{ id:'obrigacoes', topic:'produtos', o:4, title:'Obrigações', mins:6,
  lead:'Uma obrigação é um empréstimo que fazes a um Estado ou a uma empresa. Em troca, recebes juros regulares e o dinheiro de volta no fim do prazo. É a base de tudo o que se chama «rendimento fixo».',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Quando emprestas dinheiro a um amigo, combinam três coisas: quanto, até quando e quanto ele te paga por isso. Uma obrigação é esse acordo em papel (hoje, em registo eletrónico), só que o devedor pode ser um país ou uma empresa e o acordo pode ser vendido a outra pessoa a meio. Quem compra a obrigação passa a ser <b>credor</b> do emissor, ou seja, alguém a quem o emissor deve dinheiro.'},
    {t:'h',id:'h1',x:'As quatro peças de uma obrigação'},
    {t:'ul',id:'u1',x:[
      '<b>Emissor</b>: quem pede o dinheiro (o Estado, um banco, uma empresa).',
      '<b>Valor nominal</b>: a quantia que será devolvida no fim, por exemplo 1 000 € por obrigação.',
      '<b>Cupão</b>: o juro que o emissor paga, em % do nominal, normalmente uma vez por ano.',
      '<b>Maturidade</b>: a data em que o nominal é devolvido. Uma obrigação a 5 anos devolve o nominal ao fim de 5 anos.']},
    {t:'p',id:'p1',x:`Um exemplo simples. Compras 10 obrigações de 1 000 € de valor nominal (10 000 € no total) com cupão de 3% e maturidade a 5 anos, ao preço do nominal. Recebes ${_e(10000*0.03)} por ano em cupões e, no fim do quinto ano, os 10 000 € de volta. Em 5 anos recebeste ${_e(10000*0.03*5)} de juros brutos. Descontando os 28% de retenção sobre os juros (como acontece em Portugal com as obrigações), ficam ${_e(10000*0.03*0.72)} por ano.`},
    {t:'stat',id:'s1',v:10000*0.03*5,label:'juros brutos em 5 anos, sobre 10 000 € de nominal com cupão de 3% (valor de exemplo)'},
    {t:'h',id:'h2',x:'Porque é que o preço muda'},
    {t:'p',id:'p2',x:'Podes vender a obrigação antes do fim, ao preço de mercado. Esse preço <b>move-se ao contrário das taxas de juro</b>. Se as taxas sobem, as obrigações novas pagam mais e as antigas, com cupão menor, valem menos. Se as taxas descem, as antigas ficam mais valiosas. Os preços das obrigações são cotados em percentagem do nominal: 95 quer dizer 95% do nominal.'},
    {t:'p',id:'p3',x:`Um exemplo com números. Uma obrigação com cupão de 2% e 5 anos até ao fim. Se o mercado passar a exigir 4% para obrigações semelhantes, o preço que um comprador aceita pagar desce para ${_prod_n(_prod_bp(2,0.04,5))}% do nominal, uma perda de ${_prod_pc(100-_prod_bp(2,0.04,5))}. Se as taxas descerem para 1%, o preço sobe para ${_prod_n(_prod_bp(2,0.01,5))}%. Se segurares a obrigação até à maturidade, recebes o nominal (se o emissor pagar), qualquer que seja o preço pelo caminho: a perda só é real se venderes antes.`},
    {t:'h',id:'h3',x:'Quem é o emissor conta muito'},
    {t:'cmp',id:'c1',head:['Emissor','Risco de crédito','Tende a pagar'],rows:[
      ['Estados sólidos','Baixo','Menos'],
      ['Empresas de boa qualidade','Médio','Mais do que os Estados'],
      ['Empresas frágeis («lixo»)','Alto','Muito mais, mas com risco real de perda']],
      cap:'Mais risco, mais juro: é uma regra geral.'},
    {t:'p',id:'p4',x:'O risco de o emissor não pagar chama-se <b>risco de crédito</b>. Os Estados que emitem na sua própria moeda têm o risco mais baixo; os países que partilham uma moeda, como os da Zona Euro, não podem imprimir euros por conta própria, e por isso o seu risco de crédito é diferente. As empresas têm risco de crédito variável e as mais frágeis são designadas obrigações «de alto rendimento» ou «lixo» (<i>high yield</i>).'},
    {t:'h',id:'h4',x:'Um caso real: Portugal, 2011'},
    {t:'p',id:'p5',x:'Na crise da dívida na Zona Euro, os investidores começaram a duvidar de que alguns países pagassem tudo o que deviam. As obrigações do Estado português perderam valor e a taxa que o país tinha de oferecer para pedir dinheiro emprestado subiu tanto que deixou de ser comportável. Em 2011 Portugal pediu assistência financeira internacional. Foi um exemplo claro de que obrigações do Estado não são «sem risco»: dependem de quem as emite e da confiança dos credores.'},
    {t:'h',id:'h5',x:'Obrigações, depósitos e ações'},
    {t:'cmp',id:'c2',head:['','Depósito','Obrigação','Ação'],rows:[
      ['O que és','Depositante','Credor','Sócio'],
      ['O que recebes','Juro','Cupão e nominal','Dividendo e valorização'],
      ['Ordem de pagamento se a empresa falir','Garantia até 100 000 €','Antes dos acionistas','Depois de todos'],
      ['Preço','Estável','Muda com as taxas e com o crédito','Muda muito']]},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que obrigações «não perdem». O preço muda, e perdes se vendes depois de as taxas subirem.',
      'Ver só o cupão e esquecer o risco de crédito: um cupão muito alto avisa que o mercado desconfia do emissor.',
      'Comprar obrigações «de banco» pensando que estão cobertas pelo Fundo de Garantia de Depósitos, que cobre depósitos e não títulos.',
      'Comparar obrigações a 2 anos com obrigações a 30 anos sem ter em conta o risco de preço.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Em Portugal podes comprar obrigações através do teu banco ou de uma corretora, e também indiretamente, através de ETFs e fundos de obrigações. Os Certificados de Aforro e os Certificados do Tesouro não são obrigações cotadas, mas o princípio é parecido: emprestas ao Estado. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), os juros de obrigações sofrem retenção de 28% a título definitivo quando pagos por intermediário em Portugal, e as mais-valias na venda ou reembolso são tributadas a 28%, com englobamento obrigatório se detidas há menos de 365 dias e o rendimento estiver no último escalão. Para o resto, vê os temas <b>Dividendos e juros</b> e <b>Mais-valias: quanto imposto pagas ao vender</b>; para o lado avançado (yield, duração, rating), o tema <b>Obrigações a fundo</b>.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Uma obrigação é um empréstimo: o emissor paga cupões e devolve o nominal na maturidade.',
      'O preço move-se ao contrário das taxas de juro: taxas a subir fazem os preços descer.',
      'Se seguras até ao fim e o emissor paga, recebes o nominal, qualquer que seja o preço pelo caminho.',
      'Mais risco de crédito, mais juro: um cupão muito alto é um aviso.',
      'Os juros e as mais-valias pagam 28% em Portugal, segundo a AT.']},
    {t:'decide',id:'q1',ensina:['p2','p3'],label:'Decide',q:'Tens uma obrigação com cupão de 2%. As taxas de juro no mercado sobem para 4%. O que acontece ao preço da tua obrigação se a quiseres vender hoje?',o:['Sobe, porque agora é mais valiosa','Desce, porque as obrigações novas pagam mais','Fica igual até à maturidade'],c:1,why:'Quem compra prefere uma obrigação nova que paga 4% a uma antiga que paga 2%, por isso o preço da antiga desce até compensar a diferença.'},
    {t:'decide',id:'q2',ensina:['u1','p4'],label:'Decide',q:'Numa obrigação de uma empresa, o que significa «risco de crédito»?',o:['O preço pode variar com o mercado','A moeda pode perder valor','O emissor pode não conseguir pagar os juros ou o nominal'],c:2,why:'Risco de crédito é a possibilidade de o emissor falhar os pagamentos. O risco de preço e o cambial são outros.'},
    {t:'fazve',id:'q3',ensina:['p1'],q:'Compraste 10 000 € de nominal de uma obrigação com cupão de 3%. Quanto recebes de cupão líquido num ano, depois dos 28% de retenção?',unit:'€',answer:10000*0.03*0.72,tol:.02,why:'Cupão bruto: 300 €. Retenção de 28%: 84 €. Líquido: 216 €.'},
    {t:'erro',id:'q4',ensina:['p5','c1','u2'],label:'Encontra o erro',q:'Uma destas frases está errada. Qual?',o:['As obrigações do Estado nunca têm risco de crédito','Uma obrigação com cupão muito alto pode ser sinal de maior risco','Obrigações podem ser vendidas antes do fim ao preço de mercado','Se seguras até à maturidade e o emissor paga, recebes o nominal'],c:0,why:'Em 2011 as obrigações de Portugal perderam valor porque os investidores duvidaram de que o país pagasse. Mesmo os Estados têm risco de crédito.'}
  ], src:[_prod_ref] },

{ id:'obrigacoes-fundo', topic:'produtos', o:5, title:'Obrigações a fundo: yield, duração, rating e inflação', mins:9,
  lead:'Aprofunda o tema das obrigações. Aqui percebes como se mede o rendimento verdadeiro, porque as obrigações longas oscilam tanto, o que dizem os ratings, como funciona um cupão zero e o que são obrigações indexadas à inflação.',
  blocks:[
    {t:'h',id:'h0',x:'O cupão não é o rendimento'},
    {t:'p',id:'p0',x:'No tema anterior viste que o cupão é o juro fixo que a obrigação paga. Mas se comprares a obrigação a um preço diferente do nominal, o que realmente ganhas já não é o cupão. Se pagares 90 por uma obrigação que vai devolver 100 e paga 3 de cupão, ganhas o cupão e ainda os 10 de diferença no fim. Para comparar obrigações há, por isso, um número que junta tudo: a <b>yield</b>.'},
    {t:'p',id:'p1',x:'A <b>yield até à maturidade</b> (<i>yield to maturity</i>) é a taxa anual que iguala o preço de hoje a todos os pagamentos futuros (cupões e nominal), assumindo que seguras até ao fim e que o emissor paga. Há uma relação direta: <b>quando o preço sobe, a yield desce, e vice-versa</b>. A <b>yield corrente</b> é mais simples e menos útil: cupão a dividir pelo preço.'},
    {t:'cmp',id:'c1',head:['Preço pago (nominal 100, cupão 3%, 5 anos)','Yield corrente','Yield até à maturidade'],rows:[
      ['90',_prod_pc(3/90*100,2),_prod_pc(_prod_ytm(90,3,5),2)],
      ['100','3,00%','3,00%'],
      ['105',_prod_pc(3/105*100,2),_prod_pc(_prod_ytm(105,3,5),2)]],
      cap:'Valores de exemplo. A yield até à maturidade é calculada resolvendo a equação do preço.'},
    {t:'h',id:'h1',x:'Duração: a medida do medo das taxas'},
    {t:'p',id:'p2',x:'A <b>duração</b> diz-te, em anos, quanto tempo demoras em média a receber o teu dinheiro de volta (contando cupões e nominal). Dá também uma regra prática: a duração modificada indica, aproximadamente, a percentagem que o preço perde por cada ponto percentual de subida das taxas. Quanto maior a duração, mais o preço oscila.'},
    {t:'cmp',id:'c2',head:['Obrigação (cupão 3%, yield 3%)','Duração modificada (aprox. em anos)','Preço se a yield subir 1 ponto','Preço se a yield descer 1 ponto'],rows:[2,5,10,30].map(n=>[n+' anos',_prod_n(_prod_mod(3,0.03,n),1),_prod_n(_prod_bp(3,0.04,n))+'%',_prod_n(_prod_bp(3,0.02,n))+'%']),
      cap:'Preços em percentagem do nominal, partindo de 100. Valores de exemplo, calculados com cupão anual.'},
    {t:'p',id:'p3',x:`Repara na assimetria: a obrigação a 30 anos perde ${_prod_pc(100-_prod_bp(3,0.04,30))} se as taxas subirem 1 ponto e ganha ${_prod_pc(_prod_bp(3,0.02,30)-100)} se descerem. A obrigação a 2 anos mexe pouco nos dois sentidos. Quem quer pouco risco de taxas escolhe duração curta; quem aposta que as taxas vão descer pega em duração longa. Um fundo ou ETF de obrigações tem uma duração média (por exemplo 7 anos), que está no documento do produto, e funciona como indicador de risco.`},
    {t:'h',id:'h2',x:'Rating: a nota do devedor'},
    {t:'p',id:'p4',x:'Agências como a S&P, a Moody’s e a Fitch avaliam a capacidade de um emissor pagar o que deve e atribuem uma nota, o <b>rating</b>. Na escala da S&P e da Fitch, <b>AAA</b> é a nota mais alta e, descendo, vêm AA, A e BBB. Até <b>BBB-</b> chama-se <i>investment grade</i> (grau de investimento). Abaixo, de BB+ para baixo, é <i>high yield</i> (alto rendimento) ou «lixo». A Moody’s usa letras ligeiramente diferentes (Aaa, Aa, A, Baa, Ba...), mas a ideia é a mesma.'},
    {t:'cmp',id:'c3',head:['Categoria','Notas (escala S&P)','O que significa'],rows:[
      ['Grau de investimento, alto','AAA a A-','Capacidade forte de pagar; risco de crédito baixo'],
      ['Grau de investimento, baixo','BBB+ a BBB-','Capacidade adequada, mas mais sensível a más condições económicas'],
      ['Alto rendimento (lixo)','BB+ e abaixo','Risco de crédito elevado; paga mais para compensar'],
      ['Incumprimento','D','O emissor falhou um pagamento']],
      cap:'O rating é uma opinião, não uma garantia: as agências já se enganaram, como em 2008.'},
    {t:'p',id:'p5',x:'A diferença entre o que paga uma obrigação de uma empresa e o que paga uma obrigação do Estado com o mesmo prazo chama-se <b>spread de crédito</b>. Em tempos calmos, o spread é pequeno; em crises, alarga-se, porque os investidores exigem mais para correr o risco de a empresa não pagar.'},
    {t:'h',id:'h3',x:'Cupão zero: sem juros a meio, só o desconto'},
    {t:'p',id:'p6',x:`Uma obrigação de <b>cupão zero</b> não paga nada durante a vida. Compras-a abaixo do nominal e recebes o nominal no fim; a diferença é o teu rendimento. Com yield de 3%, uma obrigação de cupão zero a 10 anos que devolve 100 custa hoje ${_prod_n(100/Math.pow(1.03,10))}, e daqui a 10 anos vale 100. Como todo o dinheiro chega no fim, a duração é igual à maturidade (10 anos), o que a torna a mais sensível às taxas: uma subida de 1 ponto na yield faz o preço descer cerca de ${_prod_pc(100-100/Math.pow(1.04,10)/(100/Math.pow(1.03,10))*100)} (valor de exemplo).`},
    {t:'note',id:'n1',x:'A AT trata a diferença entre o valor de reembolso e o preço de emissão como rendimento de capitais, a parte que corresponde ao período em que detiveste o título, e retira-a do cálculo da mais-valia. Em termos práticos, o «lucro do desconto» é tributado como juro, não como mais-valia (verificado em 17/11/2026 no guia fiscal da AT).'},
    {t:'h',id:'h4',x:'Obrigações indexadas à inflação'},
    {t:'p',id:'p7',x:'Uma obrigação normal paga juros em euros fixos, por isso a inflação corrói o poder de compra do dinheiro que recebes. Numa obrigação <b>indexada à inflação</b>, o nominal (e, com ele, os cupões) é ajustado de acordo com um índice de preços. Alguns Estados da Zona Euro emitem-nas e ligam-nas a índices de preços ao consumidor (em vários casos, o índice harmonizado da Zona Euro). Em vez de uma yield nominal, o mercado indica uma <b>yield real</b>: o rendimento acima da inflação.'},
    {t:'p',id:'p8',x:`Como comparar? A <b>inflação de equilíbrio</b> (<i>breakeven</i>) é a inflação a partir da qual a obrigação indexada compensa mais do que a normal. Se uma obrigação normal a 10 anos tem yield de 3% e a indexada tem yield real de 1%, a inflação de equilíbrio é (1,03 ÷ 1,01) − 1 = ${_prod_pc((1.03/1.01-1)*100,2)}. Se a inflação média nesses 10 anos for 3%, a indexada rende, em termos nominais, 1,01 × 1,03 − 1 = ${_prod_pc((1.01*1.03-1)*100,2)}, mais do que os 3% da normal. Se for 1%, rende ${_prod_pc((1.01*1.01-1)*100,2)}, menos.`},
    {t:'stat',id:'s1',v:Number(((1.03/1.01-1)*100).toFixed(2)),fmt:'pct',label:'inflação de equilíbrio neste exemplo: acima disto a indexada ganha, abaixo perde'},
    {t:'note',id:'n2',pending:true,x:'Não confirmámos em fonte oficial como a AT trata a correção do capital ligada à inflação nas obrigações indexadas. Antes de comprar, pede à corretora a ficha fiscal do instrumento. Também não confirmámos quais obrigações indexadas se compram em corretoras portuguesas; muitas existem em ETFs UCITS.'},
    {t:'h',id:'h5',x:'Um caso real: 2022, o ano em que as obrigações caíram'},
    {t:'p',id:'p9',x:'Durante mais de uma década as taxas estiveram muito baixas e as obrigações pareciam a parte «calma» da carteira. Em 2022, para travar a inflação, os bancos centrais subiram as taxas depressa e as obrigações caíram muito, com perdas de dois dígitos em muitos fundos, sobretudo nas de prazo longo. Foi um dos piores anos de que há registo para as obrigações. Quem tinha obrigações curtas ou as segurou até à maturidade sofreu muito menos. A lição não é que as obrigações sejam más, mas que a duração se paga em volatilidade.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Ver só o cupão e não a yield: a obrigação com cupão alto pode ter sido comprada a preço alto.',
      'Ignorar a duração: um ETF de obrigações a 20 anos não é «seguro» por ter «obrigações» no nome.',
      'Fiar-se só no rating, que é uma opinião e pode estar atrasado em relação aos factos.',
      'Comprar «lixo» pela yield sem aceitar que parte do que ganhas é o preço do risco de perder.',
      'Comprar indexadas à inflação sem perceber que podem perder valor se as yields reais subirem.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p10',x:'Para obrigações do Estado português, os juros e as mais-valias têm retenção ou tributação de 28%, segundo o guia fiscal da AT (outubro de 2023, consultado em 17/11/2026); o englobamento é obrigatório se detidas há menos de 365 dias e o rendimento estiver no último escalão. Para obrigações estrangeiras e ETFs de obrigações, as regras seguem o fundo ou a corretora (vê o tema <b>Declarar no IRS: Modelo 3, anexos G e J</b>). Para quem começa, a via mais simples é um ETF UCITS de obrigações de prazo definido. Vê também o tema <b>Bancos centrais e taxas de juro</b>, que explica porque as taxas se mexem.'},
    {t:'gl',id:'g1',items:[
      ['Cupão','Juro fixo que a obrigação paga, em % do nominal.'],
      ['Maturidade','Data em que o nominal é devolvido.'],
      ['Yield até à maturidade','Taxa anual que iguala o preço aos pagamentos futuros, se seguras até ao fim.'],
      ['Duração','Tempo médio, em anos, para receber o dinheiro de volta; mede a sensibilidade às taxas.'],
      ['Spread de crédito','Diferença de yield entre um emissor com risco e o Estado do mesmo prazo.'],
      ['Investment grade','Rating BBB- ou acima.'],
      ['High yield','Rating abaixo de BBB-; paga mais, arrisca mais.'],
      ['Cupão zero','Obrigação sem cupões: compra-se com desconto e recebe-se o nominal no fim.'],
      ['Inflação de equilíbrio','Inflação a partir da qual uma obrigação indexada compensa mais do que a normal.']]},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'A yield, e não o cupão, é o número para comparar obrigações: junta cupões, preço e nominal.',
      'Preço e yield movem-se em sentidos opostos.',
      'A duração mede a sensibilidade às taxas: quanto maior, mais o preço oscila.',
      'O rating (de AAA a D) é uma opinião: abaixo de BBB- é «lixo».',
      'Cupão zero tem a duração mais alta; indexadas protegem da inflação a um custo.']},
    {t:'decide',id:'q1',ensina:['c2','p3'],label:'Decide',q:'As taxas de juro sobem 1 ponto. Qual destas obrigações com yield 3% perde mais valor?',o:['A 2 anos','A 5 anos','A 30 anos'],c:2,why:'A duração da obrigação a 30 anos é a maior, por isso é a que mais perde por cada ponto de subida das taxas.'},
    {t:'fazve',id:'q2',ensina:['p6'],q:'Uma obrigação de cupão zero a 10 anos devolve 100 e a yield é 3%. Qual é o preço, em % do nominal? (Arredonda às unidades.)',unit:'%',answer:Math.round(100/Math.pow(1.03,10)),tol:.02,why:'100 ÷ 1,03 elevado a 10 = cerca de 74. Recebes 100 daqui a 10 anos, por isso hoje só pagas cerca de 74.'},
    {t:'decide',id:'q3',ensina:['c3','p4'],label:'Decide',q:'Uma obrigação tem rating BB+. Como se classifica?',o:['Investment grade','High yield, abaixo do grau de investimento','Incumprimento'],c:1,why:'BBB- é o último nível do grau de investimento. BB+ está logo abaixo, no alto rendimento.'},
    {t:'erro',id:'q4',ensina:['p7','p8'],label:'Encontra o erro',q:'Uma destas frases sobre obrigações indexadas à inflação está errada. Qual?',o:['O nominal é ajustado de acordo com um índice de preços','A yield real mede o rendimento acima da inflação','Ganham sempre mais do que uma obrigação normal, seja qual for a inflação','A inflação de equilíbrio indica a partir de que inflação compensam'],c:2,why:'Se a inflação ficar abaixo da inflação de equilíbrio, a obrigação normal rende mais.'}
  ], src:[_prod_ref] }
);
LRN.push(
{ id:'acoes', topic:'produtos', o:6, title:'Ações', mins:6,
  lead:'Comprar ações é tornares-te sócio de uma empresa. Podes ganhar com a valorização e com os dividendos, mas o valor pode cair muito e ninguém garante o retorno.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Uma padaria precisa de dinheiro para comprar um forno novo. Em vez de pedir um empréstimo, o dono vende partes do negócio a quem queira ser sócio. Cada parte é uma <b>ação</b>. Quem a compra passa a ter direito a uma fração dos lucros e a votar nas decisões grandes da empresa, na proporção do que tem. Se a padaria prosperar, a parte vale mais; se correr mal, vale menos.'},
    {t:'p',id:'p1',x:'Numa empresa grande e cotada em bolsa, as partes são milhões e podem ser compradas e vendidas todos os dias. O preço da ação resulta da oferta e da procura: sobe quando há mais gente a querer comprar do que a vender, e desce no caso contrário. A soma do valor de todas as ações é a <b>capitalização bolsista</b> da empresa, que é o valor que o mercado lhe atribui.'},
    {t:'h',id:'h1',x:'Como ganhas (e como perdes)'},
    {t:'p',id:'p2',x:'O teu retorno vem de duas fontes: a <b>valorização</b> (vendes por mais do que compraste) e os <b>dividendos</b> (parte do lucro que a empresa distribui aos acionistas, se quiser). Pode haver anos em que uma empresa não paga dividendo, e anos em que o preço cai. O dividendo não é uma prenda: na <b>data ex-dividendo</b> o preço da ação desce, em regra, cerca do valor do dividendo, porque esse dinheiro saiu da empresa para a tua conta.'},
    {t:'p',id:'p3',x:'Como sócio, estás <b>no fim da fila</b> se a empresa falir: primeiro são pagos os credores (bancos, obrigacionistas, fornecedores), e só depois os acionistas, se sobrar alguma coisa. Por isso o risco é maior do que o de uma obrigação da mesma empresa. A perda máxima de uma ação comprada, sem alavancagem, é o valor investido: nunca ficas a dever mais do que pagaste.'},
    {t:'w',id:'w1',w:'calc',c:'payout'},
    {t:'p',id:'p4',x:'A calculadora acima mostra duas medidas que vais ver muitas vezes: o <b>payout</b>, que é a percentagem do lucro que a empresa distribui, e o <b>rendimento do dividendo</b>, que é o dividendo a dividir pelo preço. Um rendimento do dividendo muito alto pode ser um aviso, porque pode indicar que o preço caiu muito por razões sérias.'},
    {t:'h',id:'h2',x:'Um exemplo com números'},
    {t:'p',id:'p5',x:`Compraste uma ação por ${_e(50)}, recebeste ${_e(2)} de dividendo durante o ano e vendeste por ${_e(60)}. Valorização: ${_e(10)}. Dividendo: ${_e(2)}. Total: ${_e(12)} sobre ${_e(50)}, o que dá ${_prod_pc(12/50*100,0)} de retorno total antes de impostos e comissões. Se o dividendo for reinvestido, o efeito soma-se ao longo dos anos: é por isso que se fala do <b>retorno total</b> e não só da subida do preço.`},
    {t:'h',id:'h3',x:'Tipos de ações e de empresas'},
    {t:'cmp',id:'c1',head:['','Grandes empresas (large cap)','Pequenas empresas (small cap)','Empresas de dividendo','Empresas de crescimento'],rows:[
      ['Perfil','Estabelecidas, líderes do setor','Mais pequenas, menos conhecidas','Maduras, distribuem muito do lucro','Reinvestem o lucro para crescer'],
      ['Oscilação','Menor','Maior','Média','Alta'],
      ['De onde vem o retorno','Valorização e dividendo','Sobretudo valorização','Sobretudo dividendo','Sobretudo valorização'],
      ['Risco principal','Mercado','Falhar ou ser pouco líquida','Cortar o dividendo','Pagar demasiado pelo crescimento']],
      cap:'Categorias gerais; há muitas exceções dentro de cada uma.'},
    {t:'p',id:'p6',x:'Escolher ações individuais exige pesquisa, tempo e disciplina, e um erro numa só empresa pode doer. Muitos investidores preferem comprar o <b>mercado inteiro</b> através de um ETF e deixar as ações individuais para uma pequena parte da carteira, ou para nada. Para avaliar uma empresa, vê os temas do módulo de análise fundamental.'},
    {t:'h',id:'h4',x:'Um caso real: a bolha das empresas da internet'},
    {t:'p',id:'p7',x:'No final dos anos 90, as ações de empresas de internet subiram a um ritmo que não tinha ligação com os lucros, em muitos casos porque as empresas ainda nem tinham lucros. O índice tecnológico norte-americano Nasdaq atingiu o máximo em março de 2000 e, nos dois anos e meio seguintes, perdeu bem mais de metade do valor. Muitas empresas desapareceram, e quem tinha apostado tudo numa só ficou sem nada. As poucas que sobreviveram voltaram a valer mais, mas ao fim de muitos anos. O caso mostra duas coisas: o preço pode afastar-se muito do valor durante muito tempo, e concentrar o dinheiro numa única empresa ou num só setor é o erro que mais custa.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Pôr o dinheiro todo numa só empresa, ou na empresa onde trabalhas.',
      'Comprar porque «já subiu muito» ou vender por pânico quando cai.',
      'Achar que um dividendo alto é sempre bom sinal.',
      'Confundir uma boa empresa com um bom preço: pagar demais também dá prejuízo.',
      'Investir dinheiro de que podes precisar em menos de 5 anos.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p8',x:'Podes comprar ações de empresas portuguesas (na Euronext Lisboa) e de empresas estrangeiras através de um banco ou de uma corretora. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), os dividendos pagos a residentes sofrem retenção na fonte de 28% a título definitivo, quando pagos por intermediário em Portugal, e podes optar pelo englobamento, caso em que só 50% dos dividendos entram na base de tributação. As mais-valias têm tributação autónoma de 28%, com englobamento obrigatório se detiveres as ações há menos de 365 dias e o teu rendimento estiver no último escalão. Para os pormenores, vê os temas <b>Dividendos e juros</b>, <b>Mais-valias: quanto imposto pagas ao vender</b> e <b>Comissões e imposto do selo</b>. Para saber como se compra, vê <b>Banco ou corretora?</b>, <b>Tipos de ordem</b> e <b>Horários da Euronext Lisboa</b>.'},
    {t:'note',id:'n1',pending:true,x:'Para dividendos de ações estrangeiras, a retenção no país de origem e o crédito de imposto no anexo J dependem do país e da corretora. Não confirmámos a taxa de cada país em fonte oficial; confirma sempre com a tua corretora e com as convenções de dupla tributação.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Uma ação é uma parte de uma empresa; és sócio, não credor.',
      'O retorno vem da valorização e dos dividendos: é o retorno total que conta.',
      'Estás no fim da fila se a empresa falir, mas nunca perdes mais do que investiste.',
      'Uma só empresa concentra muito risco: diversificar reduz o risco sem pedir mais retorno.',
      'Em Portugal, dividendos e mais-valias pagam 28% por defeito; o englobamento é opção (ou obrigação, em casos previstos).']},
    {t:'fazve',id:'q1',ensina:['p2','p5'],q:'Compraste uma ação por 50 €, recebeste 2 € de dividendo durante o ano e vendeste por 60 €. Qual foi o retorno total, em %, antes de impostos e comissões?',unit:'%',answer:24,tol:.02,why:'Valorização: 10 €. Dividendo: 2 €. Total: 12 € sobre 50 €, ou seja, 24%.'},
    {t:'decide',id:'q2',ensina:['p3'],label:'Decide',q:'A empresa em que tens ações vai à falência. O que acontece, em regra, à tua posição?',o:['Recuperas o valor investido pelo Estado','Recebes o dobro, por seres sócio','Os credores recebem primeiro; os acionistas só recebem se sobrar algo, e muitas vezes perdem tudo'],c:2,why:'Acionistas ficam atrás dos credores. Se não sobrar nada, o valor investido perde-se, mas não perdes mais do que investiste.'},
    {t:'fazve',id:'q3',ensina:['p4','w1'],q:'Uma empresa tem lucro de 3 € por ação e paga 1,20 € de dividendo. Qual é o payout, em %?',unit:'%',answer:_c('payout',{d:1.2,l:3,p:30})[0],tol:.02,why:'1,20 ÷ 3 = 40%. A empresa distribui 40% do lucro e reinveste o resto.'},
    {t:'erro',id:'q4',ensina:['p2','p7','u1'],label:'Encontra o erro',q:'Uma destas frases sobre ações está errada. Qual?',o:['Se uma empresa falir, os acionistas são pagos antes dos credores','Os dividendos não são garantidos','O preço da ação desce, em regra, na data ex-dividendo','Concentrar tudo numa só empresa aumenta o risco'],c:0,why:'É o contrário: os credores são pagos primeiro. Os acionistas ficam no fim da fila.'}
  ], src:[_prod_ref] },

{ id:'fundos', topic:'produtos', o:7, title:'Fundos de investimento', mins:7,
  lead:'Um fundo junta o dinheiro de muitos investidores e uma sociedade gestora aplica-o. Compras uma fração do conjunto em vez de escolheres cada ativo. O que mais diferencia os fundos entre si é o custo.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Pensa num jantar de grupo em que cada pessoa põe uma quantia para uma grande mesa de comida, e uma pessoa fica encarregada de escolher os pratos. Todos comem um pouco de tudo, e cada um recebe uma parte proporcional ao que pôs. Num <b>fundo de investimento</b> o «chefe» é a sociedade gestora, a mesa são os ativos (ações, obrigações, imóveis...) e a parte de cada um chama-se <b>unidade de participação</b>.'},
    {t:'h',id:'h1',x:'Como funciona por dentro'},
    {t:'p',id:'p1',x:'O fundo é um património separado, guardado num banco depositário, que não se mistura com o da gestora. Cada investidor compra <b>unidades de participação</b>. O valor de cada uma calcula-se assim: somam-se os ativos do fundo, subtraem-se as dívidas e as comissões por pagar e divide-se pelo número de unidades. É o <b>valor da unidade de participação</b>, que se atualiza em regra uma vez por dia.'},
    {t:'p',id:'p2',x:`Um exemplo: um fundo tem ${_e(52000000)} em ativos e ${_e(2000000)} em dívidas e custos por pagar, com 5 000 000 de unidades. Cada unidade vale (${_e(52000000)} − ${_e(2000000)}) ÷ 5 000 000 = ${_e((52000000-2000000)/5000000)}. Se aplicares ${_e(1000)} no fundo, compras ${1000/((52000000-2000000)/5000000)} unidades. Quando o fundo ganha, o valor da unidade sobe; quando perde, desce. As entradas e saídas dos outros investidores não alteram o valor da tua unidade, só o número de unidades em circulação.`},
    {t:'p',id:'p3',x:'O gestor decide em que ativos investir, de acordo com a política do fundo (ações, obrigações, misto). Existem fundos de <b>gestão ativa</b>, em que o gestor tenta fazer melhor do que o mercado, e fundos <b>indexados</b>, que apenas replicam um índice. Os fundos para pequenos investidores na UE seguem normalmente as regras europeias <b>OICVM</b> (a sigla portuguesa de UCITS), que impõem limites à concentração e exigem que o investidor possa resgatar com regularidade.'},
    {t:'h',id:'h2',x:'Tipos de fundos'},
    {t:'cmp',id:'c1',head:['Tipo','Investe em','Risco típico'],rows:[
      ['Fundo de ações','Ações de empresas','Alto: oscila como o mercado de ações'],
      ['Fundo de obrigações','Dívida de Estados e empresas','Baixo a médio: depende da duração e do crédito'],
      ['Fundo misto ou multiativos','Ações e obrigações em proporções definidas','Médio: depende do equilíbrio'],
      ['Fundo monetário','Dívida de prazo muito curto','Muito baixo, mas sem garantia'],
      ['Fundo imobiliário','Imóveis ou empresas imobiliárias','Médio: pouco líquido em alguns casos'],
      ['Fundo PPR','Ações, obrigações, ou ambas, num regime fiscal próprio','Depende da composição']],
      cap:'Há mais variantes, como fundos de fundos ou setoriais. O risco depende do que está dentro, não do nome.'},
    {t:'h',id:'h3',x:'O que é que te cobram'},
    {t:'p',id:'p4',x:'O que torna os fundos diferentes é o <b>custo</b>. Pode haver comissão de subscrição (quando entras) e de resgate (quando sais), e todos têm uma comissão de gestão anual que sai diretamente do valor do fundo. Há ainda comissão de depósito e, em alguns, comissão de desempenho. O somatório dos custos anuais chama-se <b>TER</b> e deve estar no documento de informação fundamental (o KID) de cada fundo. Estes custos pesam durante décadas.'},
    {t:'w',id:'w1',w:'calc',c:'fees'},
    {t:'p',id:'p5',x:`Com ${_e(10000)} iniciais mais ${_e(200)} por mês durante 30 anos, a um retorno de 6% antes de custos, um fundo com custos de 1,5% ao ano deixa-te com ${_e(_c('fees',{ini:10000,men:200,rate:6,ter:1.5,ano:30})[1])}. Se os custos forem de 0,2%, ficas com ${_e(_c('fees',{ini:10000,men:200,rate:6,ter:0.2,ano:30})[1])}. A diferença, ${_e(_c('fees',{ini:10000,men:200,rate:6,ter:0.2,ano:30})[1]-_c('fees',{ini:10000,men:200,rate:6,ter:1.5,ano:30})[1])}, é o preço da comissão mais alta. Os números são de exemplo, mas a ordem de grandeza é real. Vê o tema <b>Custos e TER</b>, no módulo de carteira.`},
    {t:'h',id:'h4',x:'Fundo e ETF lado a lado'},
    {t:'cmp',id:'c2',head:['','Fundo de investimento','ETF'],rows:[
      ['Como se compra','Junto da gestora ou do banco, ao preço do fim do dia','Em bolsa, a qualquer hora de negociação'],
      ['Gestão','Frequentemente ativa','Quase sempre passiva (replica um índice)'],
      ['Custos','Geralmente mais altos','Geralmente mais baixos'],
      ['Preço','Calculado uma vez por dia','Muda ao longo do dia']],
      cap:'Há exceções nos dois lados.'},
    {t:'h',id:'h5',x:'Um caso real: quando o fundo fecha as portas'},
    {t:'p',id:'p6',x:'Em 2019, um fundo britânico de ações muito conhecido, gerido por um gestor famoso, suspendeu os resgates porque tinha muitos investidores a querer sair e grande parte da carteira estava em empresas pouco líquidas, que não se conseguiam vender depressa sem grande perda. Os investidores ficaram com o dinheiro preso durante meses. O caso mostra um risco de que pouco se fala: um fundo que promete resgates frequentes mas tem ativos difíceis de vender pode ter de «fechar a porta» no pior momento. Por isso se desconfia de fundos com ativos pouco líquidos que prometem liquidez diária.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Escolher um fundo pelo retorno do ano passado: o desempenho passado não prevê o futuro.',
      'Ignorar as comissões: 1% ao ano parece pouco, mas pesa durante décadas.',
      'Pagar comissão de subscrição e depois comissão de gestão alta por um fundo que só replica um índice.',
      'Comprar um fundo sem ler o documento de informação fundamental (KID).',
      'Confundir o nome do fundo com o que está lá dentro: lê a política de investimento.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Em Portugal os fundos são geridos por sociedades gestoras autorizadas e supervisionadas pela CMVM, que mantém uma lista no seu site. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), nos fundos mobiliários portugueses os rendimentos distribuídos e o resgate sofrem retenção na fonte de 28% a título definitivo, e a venda das unidades tem tributação autónoma de 28%; nos fundos não residentes (por exemplo irlandeses ou luxemburgueses), as distribuições e as mais-valias são tributadas a 28% e declaram-se no anexo J. Vê o tema <b>Indexado ou gestão ativa</b> e o tema <b>Declarar no IRS: Modelo 3, anexos G e J</b>.'},
    {t:'note',id:'n2',pending:true,x:'O indicador de risco de 1 a 7 e o horizonte de detenção recomendado aparecem no KID (documento de informação fundamental) de cada produto. Não confirmámos em fonte oficial os detalhes do regime europeu (PRIIPs); confirma sempre no KID do fundo concreto.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Um fundo junta o dinheiro de muitos investidores e compras unidades de participação.',
      'O valor da unidade é (ativos − dívidas) ÷ número de unidades e muda todos os dias.',
      'Há fundos de ações, obrigações, mistos, monetários, imobiliários e PPR; o risco está no que têm dentro.',
      'Os custos anuais (TER) e as comissões pesam durante décadas.',
      'Fundos com ativos pouco líquidos podem suspender resgates em tempos de pânico.']},
    {t:'decide',id:'q1',ensina:['p3','c2'],label:'Decide',q:'Qual destes produtos é tipicamente de gestão ativa, com um gestor a escolher onde investir?',o:['Um fundo de ações cujo gestor escolhe as empresas','Um ETF que replica o S&P 500','Um depósito a prazo'],c:0,why:'O gestor do fundo de ações decide o que comprar e vender. O ETF apenas replica o índice.'},
    {t:'erro',id:'q2',ensina:['p4','w1','p5'],label:'Encontra o erro',q:'Uma destas frases sobre os custos dos fundos está errada. Qual?',o:['Há uma comissão de gestão anual','Os custos saem do valor do fundo ao longo do tempo','Os custos não têm impacto no retorno no longo prazo','Pode haver comissões de subscrição e de resgate'],c:2,why:'Custos pequenos, repetidos todos os anos, acumulam-se e reduzem bastante o retorno a longo prazo.'},
    {t:'fazve',id:'q3',ensina:['p1','p2'],q:'Um fundo tem 52 milhões de euros em ativos, 2 milhões em dívidas e custos por pagar, e 5 milhões de unidades. Qual é o valor de cada unidade de participação, em euros?',unit:'€',answer:(52000000-2000000)/5000000,tol:.01,why:'(52 000 000 − 2 000 000) ÷ 5 000 000 = 10 €.'},
    {t:'decide',id:'q4',ensina:['p6'],label:'Decide',q:'Porque é que um fundo com ativos pouco líquidos pode suspender resgates numa crise?',o:['Porque a lei obriga sempre a suspender quando o mercado cai','Porque muitos investidores querem sair ao mesmo tempo e o fundo não consegue vender os ativos depressa sem grande perda','Porque o gestor decidiu ficar com o dinheiro'],c:1,why:'Se o fundo promete resgates regulares mas os ativos demoram a vender, uma onda de saídas obriga a suspender ou a vender com prejuízo.'}
  ], src:[_prod_ref,_CMVM] }
);
LRN.push(
{ id:'etf-portugal', topic:'produtos', o:8, title:'ETFs e diversificação: o que se compra em Portugal', mins:6,
  lead:'Um ETF é um fundo que se compra e vende em bolsa como uma ação e que replica um índice. Com um só produto ficas exposto a centenas de empresas, e é essa a grande vantagem para quem está a começar.',
  blocks:[
    {t:'scene',id:'sc',s:'etf',alt:"Catorze pontos de cores diferentes, que são empresas, juntam-se num único círculo, o ETF.",cap:"Muitas empresas, um só produto."},
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Em vez de comprares uma maçã de cada pomar, compras um cabaz já feito com maçãs de centenas de pomares, na mesma proporção em que os pomares existem. O <b>ETF</b> (<i>exchange-traded fund</i>, fundo negociado em bolsa) é esse cabaz: tem dentro, por exemplo, as 500 maiores empresas americanas, e tu compras uma fração dele com um clique, no preço da bolsa, a qualquer hora em que ela estiver aberta.'},
    {t:'p',id:'p1',x:'Isso é <b>diversificação</b>: se uma empresa corre mal, as outras compensam. Em vez de apostar numa, apostas no conjunto. E como o ETF apenas replica um índice, sem um gestor a escolher ações, os custos anuais costumam ser baixos, muitas vezes abaixo de 0,3% ao ano.'},
    {t:'h',id:'h1',x:'Quanto é que diversificar ajuda?'},
    {t:'p',id:'p2',x:`Uma ação tem, vamos supor, uma oscilação típica de 30% ao ano. Se juntares ações de empresas que não se influenciam umas às outras, a oscilação da carteira diminui à medida que juntas mais. Mas as empresas não são independentes: quase todas sofrem quando a economia para. Vamos supor que a correlação média entre elas é 0,3 (valor de exemplo). A tabela mostra o que acontece.`},
    {t:'cmp',id:'c1',head:['Número de ações','Oscilação, se fossem independentes','Oscilação, com correlação de 0,3'],rows:[1,5,10,50,500].map(n=>[String(n),_prod_pc(30/Math.sqrt(n)),_prod_pc(30*Math.sqrt(0.3+0.7/n))]),
      cap:'Oscilação anual de cada ação: 30% (valor de exemplo). A fórmula é: oscilação × raiz quadrada de (correlação + (1 − correlação) ÷ número de ações).'},
    {t:'p',id:'p3',x:`Duas lições. A primeira: ir de 1 para 10 ações reduz muito o risco (de ${_prod_pc(30)} para ${_prod_pc(30*Math.sqrt(0.3+0.7/10))}). A segunda: passar de 50 para 500 quase não muda nada, porque o que sobra no limite, cerca de ${_prod_pc(30*Math.sqrt(0.3))}, é o <b>risco de mercado</b>, que afeta todas as ações ao mesmo tempo e que a diversificação não elimina. Diversificar protege-te do risco de uma empresa em particular, não do risco de a bolsa cair.`},
    {t:'h',id:'h2',x:'Acumulação ou distribuição, e o que é UCITS'},
    {t:'p',id:'p4',x:'Há duas versões do mesmo ETF. <b>Acumulação (Acc)</b> reinveste os dividendos dentro do fundo; <b>distribuição (Dist)</b> paga-os na conta. A sigla «UCITS» indica que o fundo cumpre as regras europeias e pode ser vendido a particulares na UE. É o selo que procuras ao escolher um ETF a partir de Portugal.'},
    {t:'pt',id:'pt1',pt:'sp500'},
    {t:'h',id:'h3',x:'Tipos de ETF'},
    {t:'cmp',id:'c2',head:['Tipo','Replica','Para que serve','Cuidado'],rows:[
      ['Ações, mercado largo','Um índice de muitas empresas (por exemplo mundial, S&P 500, Europa)','Núcleo de uma carteira','Oscilam como as bolsas'],
      ['Obrigações','Um índice de dívida pública ou de empresas','Reduzir oscilação','A duração conta: vê o tema Obrigações a fundo'],
      ['Setoriais e temáticos','Um setor ou tema (tecnologia, saúde, energia)','Apostar num tema','Muito mais concentrados do que parecem'],
      ['Matérias-primas e ouro','Preço do ouro, petróleo, etc.','Diversificar','Sem rendimento próprio; vê o tema Ouro'],
      ['Monetários','Taxas de curto prazo','Guardar dinheiro a curto prazo','Não são depósitos']],
      cap:'Há ainda ETFs alavancados e inversos, que são para quem sabe exatamente o que faz (vê o tema Opções, CFD e alavancagem).'},
    {t:'h',id:'h4',x:'Como escolher um ETF'},
    {t:'ul',id:'u1',x:[
      '<b>Índice</b>: o que está lá dentro e em que proporção.',
      '<b>TER</b>: o custo anual, que sai do valor do ETF sem que dês por isso.',
      '<b>Dimensão</b>: ETFs muito pequenos têm mais risco de fechar.',
      '<b>Acumulação ou distribuição</b>, e a <b>moeda</b> do ETF.',
      '<b>Domicílio e replicação</b>: explicados no tema ETFs por dentro.']},
    {t:'h',id:'h5',x:'Um caso real: 2008, quando tudo caiu junto'},
    {t:'p',id:'p5',x:'Na crise financeira de 2008, muitas bolsas e muitos setores caíram ao mesmo tempo, mesmo as que pareciam diferentes. As correlações subiram precisamente quando mais precisavas de diversificação. Quem tinha só ações, mesmo muitas, perdeu muito. Quem tinha também obrigações de Estados sólidos perdeu menos. A lição é que diversificar por <b>tipo de ativo</b> (ações, obrigações, liquidez) conta tanto como diversificar por empresas. Em 2010, num dia de pânico na bolsa americana, alguns ETFs chegaram a negociar durante minutos a preços absurdos, longe do valor do que tinham dentro: uma razão para usares ordens com preço limite.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Comprar muitos ETFs que acabam por ter as mesmas empresas dentro e achar que estás diversificado.',
      'Comprar um ETF temático pelo nome, sem ver o que tem e o peso de cada empresa.',
      'Usar ordens «ao mercado» em ETFs pouco negociados.',
      'Escolher só pelo TER mais baixo, sem ver o índice, o tamanho e a replicação.',
      'Tentar comprar o VOO, o SPY ou o VTI a partir de Portugal e achar que a corretora está avariada.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Os ETFs americanos mais conhecidos, como o VOO, o SPY ou o VTI, <b>não se compram em Portugal</b>, porque não têm o documento europeu exigido (o KID). Em Portugal compras ETFs UCITS, que replicam os mesmos índices (como a ficha acima mostra para o S&P 500). Compram-se através de um banco ou corretora com acesso a bolsas europeias. Segundo o guia fiscal da AT (outubro de 2023, consultado em 17/11/2026), os fundos não residentes, que incluem os ETFs irlandeses e luxemburgueses, têm distribuições tributadas a 28% (declaradas no anexo J) e mais-valias tributadas a 28%. Vê o tema <b>ETFs de acumulação e de distribuição</b> e o tema <b>Banco ou corretora?</b>.'},
    {t:'note',id:'n1',pending:true,x:'O regime exato dos ETFs de acumulação (quando é que o ganho é tributado, se só na venda) não ficou confirmado em fonte oficial. Confirma no tema ETFs de acumulação e de distribuição e na AT antes de decidires.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Um ETF é um cabaz que se negoceia em bolsa e replica um índice, com custos baixos.',
      'Diversificar reduz o risco de cada empresa, mas não o risco de mercado.',
      'Diversifica por tipo de ativo e não só por empresas: em crises, as bolsas caem juntas.',
      'Acc reinveste os dividendos dentro do fundo; Dist paga-os na conta; UCITS é o selo europeu.',
      'Os ETFs americanos (VOO, SPY, VTI) não se compram em Portugal; as versões UCITS replicam os mesmos índices.']},
    {t:'decide',id:'q1',ensina:['pt1','p6'],label:'Decide',q:'Queres investir no S&P 500 a partir de Portugal. Qual destas opções é possível para um particular?',o:['Comprar o VOO (ETF americano)','Comprar o SPY (ETF americano)','Comprar um ETF UCITS que replica o S&P 500','Nenhuma: não é possível'],c:2,why:'Os ETFs americanos não têm o KID europeu, por isso as corretoras da UE não os vendem a particulares. Os ETFs UCITS (por exemplo domiciliados na Irlanda) replicam o mesmo índice e estão disponíveis.'},
    {t:'erro',id:'q2',ensina:['p4'],label:'Encontra o erro',q:'Uma destas frases sobre o iShares Core S&P 500 UCITS ETF (Acc) está errada. Qual?',o:['Replica o índice S&P 500','Reinveste os dividendos dentro do fundo','Paga os dividendos na tua conta todos os trimestres','Cumpre as regras europeias UCITS'],c:2,why:'A sigla (Acc) significa acumulação: os dividendos são reinvestidos no fundo e não são pagos na conta. Para receber dividendos na conta, teria de ser uma versão de distribuição (Dist).'},
    {t:'fazve',id:'q3',ensina:['p2','c1','p3'],q:'Com ações de oscilação de 30% e correlação média de 0,3, qual é aproximadamente a oscilação de uma carteira de 10 ações, em %?',unit:'%',answer:Number((30*Math.sqrt(0.3+0.7/10)).toFixed(1)),tol:.02,why:'30 × raiz quadrada de (0,3 + 0,7 ÷ 10) = cerca de 18,2%. Passar de 1 para 10 ações reduz muito a oscilação, mas o risco de mercado fica.'},
    {t:'decide',id:'q4',ensina:['p3','p5'],label:'Decide',q:'Tens 20 ETFs de ações de países diferentes. Em 2008, o mercado cai em todo o lado. O que é mais provável?',o:['Caem todos, porque o risco de mercado afeta todas as bolsas ao mesmo tempo','Os ETFs de países diferentes ficam protegidos uns pelos outros','Só caem os de países pequenos'],c:0,why:'A diversificação por países e empresas reduz o risco específico, mas em crises globais a correlação sobe e o risco de mercado fica.'}
  ], src:[{l:'justETF: ETFs domiciliados nos EUA e a regra PRIIPs',u:'https://www.justetf.com/news/etf/us-domiciled-etfs.html'},_prod_ref] },

{ id:'etfs-por-dentro', topic:'produtos', o:9, title:'ETFs por dentro: replicação, tracking difference e domicílio', mins:9,
  lead:'Dois ETFs com o mesmo nome de índice podem render de forma diferente. Aqui vês porquê: como o ETF consegue replicar um índice, o que é a tracking difference, o que muda entre Irlanda e Luxemburgo e porque é que os dividendos chegam ao teu bolso com impostos pelo caminho.',
  blocks:[
    {t:'h',id:'h0',x:'O que existe dentro da caixa'},
    {t:'p',id:'p0',x:'No tema anterior viste que um ETF é um cabaz que replica um índice. Mas «replicar» pode querer dizer coisas diferentes. O índice é apenas uma lista com regras (por exemplo, as 500 maiores empresas dos EUA). Para que o ETF dê o mesmo retorno, o gestor tem de montar uma carteira equivalente. Há duas grandes formas de o fazer, e o que mudam é onde estão os riscos.'},
    {t:'h',id:'h1',x:'Replicação física: comprar o que está no índice'},
    {t:'p',id:'p1',x:'Na <b>replicação física completa</b>, o ETF compra todas as ações do índice, na proporção certa. Na <b>replicação por amostragem</b>, compra apenas uma seleção que se comporta de forma muito parecida, o que poupa custos em índices com milhares de títulos. Em qualquer dos casos, as ações pertencem ao fundo e estão guardadas num banco depositário, separadas do património do emissor do ETF.'},
    {t:'p',id:'p2',x:'Muitos ETFs físicos fazem ainda <b>empréstimo de títulos</b>: emprestam parte das ações a quem as queira vender a descoberto e cobram uma taxa por isso. O rendimento extra reduz os custos para ti, mas cria um risco pequeno (quem pediu emprestado pode falhar). O que cobre esse risco é a garantia que o fundo recebe, e isso deve estar descrito no prospeto.'},
    {t:'h',id:'h2',x:'Replicação sintética: um contrato em vez das ações'},
    {t:'p',id:'p3',x:'Num ETF <b>sintético</b>, o fundo não compra as ações do índice. Faz um contrato (<i>swap</i>) com um banco: o fundo entrega-lhe o dinheiro, e o banco compromete-se a pagar o retorno exato do índice. A vantagem é poder acompanhar índices difíceis de comprar diretamente, com menos custos. O risco novo é o de <b>contraparte</b>: se o banco falhar, o fundo pode perder o que o banco lhe devia. Os fundos recebem garantias do banco para cobrir esse risco, e os limites estão no prospeto.'},
    {t:'cmp',id:'c1',head:['','Física completa','Física por amostragem','Sintética (swap)'],rows:[
      ['O fundo tem','Todas as ações do índice','Parte das ações, escolhidas','Uma carteira de garantia e um contrato'],
      ['Risco extra','Empréstimo de títulos','Empréstimo de títulos e desvio da carteira','Contraparte (o banco do swap)'],
      ['Transparência','Alta','Média','Média a baixa, vê o prospeto'],
      ['Custos','Tipicamente mais altos','Mais baixos','Podem ser mais baixos'],
      ['Para quê','Índices grandes e líquidos','Índices com milhares de títulos','Índices difíceis de replicar']],
      cap:'Não há uma forma melhor para todos os casos. A informação está no prospeto do ETF e na página do produto.'},
    {t:'note',id:'n1',pending:true,x:'As regras europeias (UCITS) impõem limites à exposição a uma contraparte e à concentração. Não confirmámos os valores exatos em fonte oficial, por isso não os escrevemos aqui. Lê o prospeto do ETF concreto.'},
    {t:'h',id:'h3',x:'Tracking difference: a diferença que se paga'},
    {t:'p',id:'p4',x:'Um ETF nunca rende exatamente o mesmo que o índice. A <b>tracking difference</b> é a diferença entre o retorno do ETF e o do índice, ao longo de um período. Vem sobretudo do TER (o custo anual), mas também dos impostos pagos pelo fundo sobre os dividendos, dos custos de negociar e do que ganha com o empréstimo de títulos. Um ETF bem gerido pode até ter uma tracking difference menor do que o TER, porque o empréstimo de títulos compensa parte dos custos.'},
    {t:'p',id:'p5',x:'Não confundir com <b>tracking error</b>, que mede a variabilidade dessa diferença de dia para dia. A tracking difference diz quanto perdeste; o tracking error diz com que regularidade o ETF acompanha o índice.'},
    {t:'p',id:'p6',x:`Um exemplo com números. O índice rende 8% ao ano durante 10 anos. Um ETF A com tracking difference de −0,10% ao ano rende 7,90%; um ETF B com −0,60% rende 7,40%. Com ${_e(10000)} iniciais, o ETF A termina em ${_e(10000*Math.pow(1.079,10))}, o B em ${_e(10000*Math.pow(1.074,10))} e o índice, em ${_e(10000*Math.pow(1.08,10))}. A diferença entre A e B, ${_e(10000*Math.pow(1.079,10)-10000*Math.pow(1.074,10))}, vem só de 0,50 pontos por ano.`},
    {t:'stat',id:'s1',v:Math.round(10000*Math.pow(1.079,10)-10000*Math.pow(1.074,10)),label:'diferença em 10 anos sobre 10 000 € por 0,5 pontos de tracking difference ao ano (valor de exemplo)'},
    {t:'h',id:'h4',x:'Domicílio: onde está registado o fundo'},
    {t:'p',id:'p7',x:'O <b>domicílio</b> é o país onde o ETF está registado. A maioria dos ETFs UCITS que se compram em Portugal está domiciliada na <b>Irlanda</b> ou no <b>Luxemburgo</b>, países com experiência na gestão de fundos, regras fiscais pensadas para fundos e acesso fácil ao mercado europeu. O domicílio não muda as regras de proteção UCITS, mas muda o que acontece aos dividendos antes de chegarem ao fundo.'},
    {t:'p',id:'p8',x:'Quando uma empresa paga dividendo, o país da empresa costuma reter imposto na fonte antes de pagar. Um ETF que tem ações americanas recebe dividendos já com essa retenção descontada, e isso reduz o retorno do ETF sem que tu vejas. O domicílio do fundo conta, porque os acordos entre países (convenções de dupla tributação) podem baixar a retenção para quem é residente num país com acordo. Essa é uma das razões habituais para muitos ETFs de ações americanas estarem domiciliados na Irlanda.'},
    {t:'note',id:'n2',pending:true,x:'Não confirmámos em fonte oficial as taxas de retenção sobre dividendos americanos para fundos irlandeses e luxemburgueses, nem a vantagem exata de um domicílio sobre o outro. A explicação habitual é que a Irlanda tem uma convenção com os EUA que reduz a retenção. Confirma sempre na página do ETF e no prospeto.'},
    {t:'p',id:'p9',x:'Para o investidor português, o que importa é que o ETF é um fundo <b>não residente</b>. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), as distribuições de fundos não residentes são tributadas autonomamente à taxa de 28% (quadro 8A do anexo J, código E22), e as mais-valias do resgate ou da venda também a 28% (quadro 9.2A do anexo J, código G20), com opção pelo englobamento. A taxa em Portugal é a mesma, seja o ETF irlandês ou luxemburguês: o que muda é a retenção que ficou lá fora antes de o dividendo entrar no fundo.'},
    {t:'h',id:'h5',x:'Os outros custos que não aparecem no TER'},
    {t:'ul',id:'u1',x:[
      '<b>Spread</b>: a diferença entre o preço de compra e o preço de venda em bolsa. Em ETFs pouco negociados pode ser grande.',
      '<b>Comissões da corretora</b> e, em Portugal, o imposto do selo sobre essas comissões (vê o tema Comissões e imposto do selo).',
      '<b>Câmbio</b>, se o ETF estiver em dólares ou se a tua conta for em euros e o ETF noutra moeda.',
      '<b>Impostos</b> sobre dividendos e mais-valias, que não fazem parte do TER mas pesam no retorno final.']},
    {t:'h',id:'h6',x:'Um caso real: o receio dos swaps depois de 2008'},
    {t:'p',id:'p10',x:'A falência do banco Lehman Brothers, em 2008, mostrou que um grande banco pode falhar de um dia para o outro. Depois disso, os reguladores e muitos investidores passaram a olhar com mais atenção para o risco de contraparte, incluindo o dos ETFs sintéticos, que dependem de um contrato com um banco. Os ETFs sintéticos não são proibidos nem perigosos por natureza, mas pedem mais leitura: quem é a contraparte, que garantias existem, o que acontece se falhar. O caso é um bom exemplo de que «replicar o mesmo índice» pode ter riscos diferentes por baixo.'},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Escolher o ETF só pelo TER mais baixo e ignorar o tamanho, o spread e a tracking difference real.',
      'Pensar que um ETF sintético é «falso» ou que um físico é «sem risco».',
      'Esquecer que o dividendo já vem com retenção e que Portugal ainda cobra 28% por cima.',
      'Comprar um ETF muito pequeno que pode ser fechado, o que obriga a vender quando não querias.',
      'Confundir o domicílio do ETF com a moeda em que negoceia ou com o domicílio da corretora.']},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p11',x:'Em Portugal compras ETFs UCITS, e os mais comuns estão domiciliados na Irlanda ou no Luxemburgo, o que quer dizer que são fundos não residentes para efeitos de IRS. Antes de comprar, abre a página do ETF (por exemplo na justETF) e confirma: <b>ISIN</b> (o código do produto, que começa por IE para Irlanda e LU para Luxemburgo), <b>domicílio</b>, <b>replicação</b>, <b>TER</b>, <b>dimensão</b>, <b>acumulação ou distribuição</b> e <b>moeda</b>. Os ETFs americanos (VOO, SPY, VTI) não se compram cá, porque não têm o KID europeu. Para os impostos, vê os temas <b>ETFs de acumulação e de distribuição</b> e <b>Declarar no IRS: Modelo 3, anexos G e J</b>.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Replicação física compra as ações; sintética faz um contrato (swap) com um banco e acrescenta risco de contraparte.',
      'A tracking difference é a diferença de retorno entre o ETF e o índice; vem sobretudo do TER.',
      'O domicílio (Irlanda ou Luxemburgo) conta para a retenção sobre dividendos dentro do fundo.',
      'Em Portugal, ETFs não residentes pagam 28% sobre distribuições e mais-valias, segundo a AT.',
      'Antes de comprar, confirma ISIN, domicílio, replicação, TER, dimensão, Acc/Dist e moeda.']},
    {t:'fazve',id:'q1',ensina:['p4','p6'],q:'O índice rende 8% ao ano durante 10 anos. O ETF A tem tracking difference de −0,10% e o ETF B de −0,60%. Aplicas 10 000 € em cada um. Quanto mais tens no A do que no B ao fim dos 10 anos, em euros? (Arredonda às unidades.)',unit:'€',answer:Math.round(10000*Math.pow(1.079,10)-10000*Math.pow(1.074,10)),tol:.02,why:'O ETF A rende 7,9% e o B 7,4%. A: 10 000 × 1,079 elevado a 10. B: 10 000 × 1,074 elevado a 10. A diferença é a que vês aqui.'},
    {t:'decide',id:'q2',ensina:['p3','c1','n1'],label:'Decide',q:'Qual é o risco que existe num ETF sintético e que não existe da mesma forma num ETF físico completo?',o:['O risco de o banco do swap falhar (risco de contraparte)','O risco de o índice não existir','O risco de as ações estarem em Portugal'],c:0,why:'No ETF sintético, o retorno do índice é prometido por um banco. Se o banco falhar, o fundo pode perder o que ele lhe devia.'},
    {t:'decide',id:'q3',ensina:['p8','p9'],label:'Decide',q:'Um ETF de ações americanas domiciliado na Irlanda distribui dividendos a um investidor residente em Portugal. Como são tributados em Portugal, segundo a AT?',o:['Estão isentos, porque o fundo é estrangeiro','A 28%, como fundo não residente, com declaração no anexo J','Só se forem vendidos'],c:1,why:'As distribuições de fundos não residentes são tributadas autonomamente à taxa de 28% e declaram-se no anexo J. A retenção feita no estrangeiro, dentro do fundo, é um custo à parte.'},
    {t:'erro',id:'q4',ensina:['p4','p5','u1'],label:'Encontra o erro',q:'Uma destas frases está errada. Qual?',o:['A tracking difference vem sobretudo do TER','O tracking error mede a regularidade com que o ETF acompanha o índice','O TER é o único custo de um ETF','O spread entre compra e venda é um custo'],c:2,why:'Há outros custos além do TER: o spread, as comissões da corretora, o câmbio e os impostos.'}
  ], src:[_prod_ref,{l:'justETF: ETFs domiciliados nos EUA e a regra PRIIPs',u:'https://www.justetf.com/news/etf/us-domiciled-etfs.html'}] }
);
const _prod_asf={l:'ASF: Portal do Consumidor, seguros de capitalização',u:'https://www.consumidor.asf.com.pt/pt/poupan%C3%A7a/seguros-de-capitaliza%C3%A7%C3%A3o'};
const _prod_bpdep={l:'Banco de Portugal, Portal do Cliente Bancário: prospeto de um depósito indexado («produto financeiro complexo»)',u:'https://clientebancario.bportugal.pt/sites/default/files/prospeto/Caixa%20TOP%20Agosto%202015_2.pdf'};
// Estruturado de exemplo: participação 60% na subida do índice, teto de 25% no total, mínimo 0%, 5 anos
const _prod_est=v=>Math.min(Math.max(0.6*v,0),0.25);

LRN.push(
{ id:'ppr', topic:'produtos', o:10, title:'PPR: poupança com benefício fiscal', mins:7,
  lead:'Um PPR (Plano Poupança Reforma) é um produto pensado para a reforma que dá uma dedução no IRS. Vem em vários formatos, e o benefício vem com condições: o dinheiro tem de ficar lá.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Imagina um cofre com um desconto à entrada e um cadeado que só abre ao fim de alguns anos. O Estado dá-te um desconto no imposto por pores lá dinheiro, mas só se prometeres não lhe mexer, salvo em situações previstas na lei. Um <b>PPR</b> não é, em si, um produto de investimento: é um <b>regime fiscal</b> aplicado a um fundo, a um seguro ou a outro formato autorizado. Dentro dele podes ter ações, obrigações ou ambas.'},
    {t:'p',id:'p1',x:'Um PPR pode ser um <b>fundo</b>, um <b>seguro</b> ou outro formato autorizado. Não tem capital garantido por defeito: a garantia depende do produto. E tem custos de gestão, tal como os fundos. Por isso a pergunta não é só «tem benefício fiscal?», mas também «o que está lá dentro e quanto custa?».'},
    {t:'h',id:'h1',x:'O benefício no IRS'},
    {t:'p',id:'p2',x:'Podes deduzir à coleta do IRS <b>20% do valor aplicado em cada ano</b>, até um limite que depende da tua idade a 1 de janeiro desse ano. A coleta é o imposto que apuras antes de deduções: se o teu IRS a pagar for pequeno, a dedução pode não ser aproveitada por inteiro.'},
    {t:'cmp',id:'c1',head:['Idade a 1 de janeiro','Limite da dedução','Valor a aplicar para chegar ao limite (20%)'],rows:[
      ['Menos de 35 anos','400 €',_e(400/0.2)],
      ['De 35 a 50 anos','350 €',_e(350/0.2)],
      ['Mais de 50 anos','300 €',_e(300/0.2)]],
      cap:'Valores do Estatuto dos Benefícios Fiscais (art. 21.º) e do guia fiscal da AT, verificados em 17/11/2026. Confirma o valor do ano em causa.'},
    {t:'p',id:'p3',x:`Repara que aplicar mais do que ${_e(1750)} por ano (para quem tem entre 35 e 50 anos) já não aumenta a dedução. A dedução funciona como um ganho imediato de 20% sobre o que aplicas, até ao limite. Se aplicares ${_e(1750)} por ano durante 20 anos, as deduções somam ${_e(350*20)}, desde que tenhas coleta suficiente todos os anos.`},
    {t:'h',id:'h2',x:'A condição: o dinheiro tem de ficar'},
    {t:'p',id:'p4',x:'Para manter o benefício, o dinheiro só pode ser levantado sem penalização <b>passados 5 anos</b> e em situações previstas na lei. Segundo o guia fiscal da AT, essas situações incluem a reforma por velhice, o desemprego de longa duração, a incapacidade permanente para o trabalho, a doença grave, a idade de 60 anos, a frequência de ensino profissional ou superior e o pagamento de prestações de crédito à habitação própria e permanente.'},
    {t:'p',id:'p5',x:'Fora dessas situações, o benefício fica sem efeito e as importâncias deduzidas são acrescidas à coleta, <b>majoradas em 10% por cada ano ou fração</b>, desde o ano em que deduziste. Por exemplo, uma dedução de 350 € que tenha de ser devolvida, contando 3 anos ou frações, passa a 350 € × 1,3 = 455 €. Ou seja, levantar fora de tempo custa mais do que o benefício que tiveste.'},
    {t:'h',id:'h3',x:'E o imposto quando levantas?'},
    {t:'p',id:'p6',x:`O guia fiscal da AT indica que, se o reembolso ocorrer nas condições previstas na lei e for total ou parcial (incluindo prestações durante um período não superior a dez anos), só os juros são tributados, como rendimentos de capitais: a matéria coletável é 2/5 do rendimento, tributada à taxa de 20% (com opção pelo englobamento). Na prática, a taxa efetiva sobre o ganho é de 2/5 × 20% = ${_prod_pc(0.4*20)}. Se o reembolso for feito por prestações regulares e periódicas, seguem as regras dos rendimentos de pensões (categoria H). Fora das condições da lei, o rendimento é tributado a 21,5%.`},
    {t:'note',id:'n1',pending:true,x:'O guia fiscal da AT é de outubro de 2023. O tratamento do levantamento de PPR, o valor do limite e as situações de resgate podem ter mudado. Confirma no Portal das Finanças no ano em que fores levantar.'},
    {t:'h',id:'h4',x:'Os custos podem comer o benefício'},
    {t:'p',id:'p7',x:`Imagina que aplicas ${_e(150)} por mês (${_e(1800)} por ano) durante 20 anos, com um retorno de 5% antes de custos. Com custos totais de 1,8% ao ano, acabas com ${_e(_c('fees',{ini:0,men:150,rate:5,ter:1.8,ano:20})[1])}; com custos de 0,4%, acabas com ${_e(_c('fees',{ini:0,men:150,rate:5,ter:0.4,ano:20})[1])}. A diferença, ${_e(_c('fees',{ini:0,men:150,rate:5,ter:0.4,ano:20})[1]-_c('fees',{ini:0,men:150,rate:5,ter:1.8,ano:20})[1])}, é da mesma ordem de grandeza das deduções de ${_e(350*20)} no mesmo período: um produto caro pode anular o benefício fiscal. Os números são de exemplo. Vê o tema <b>PPR ou investir por conta própria</b>.`},
    {t:'h',id:'h5',x:'Um caso real: o risco de ter tudo em ações perto da reforma'},
    {t:'p',id:'p8',x:'Na crise financeira de 2008, as bolsas caíram com muita força. Quem estava a poucos anos da reforma e tinha o PPR todo em ações viu o capital encolher quando já não tinha tempo para esperar pela recuperação. Foi um exemplo do <b>risco de sequência</b>: o mesmo retorno médio tem consequências muito diferentes conforme chega no início ou no fim da vida de poupança. Por isso muitos PPR reduzem o peso das ações à medida que o participante envelhece, e por isso convém olhar para a política de investimento e não só para o desconto fiscal.'},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Subscrever um PPR só pela dedução, sem ver os custos e o que há lá dentro.',
      'Aplicar mais do que o necessário para chegar ao limite da dedução e depois precisar do dinheiro.',
      'Levantar antes de 5 anos, fora das situações previstas: devolves a dedução com 10% a mais por cada ano ou fração.',
      'Esquecer que a dedução só ajuda se tiveres coleta suficiente.',
      'Achar que um PPR garante o capital: depende do produto.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p9',x:'O PPR é um regime português, por isso não há equivalente estrangeiro a procurar: as contas americanas (401k, IRA, Roth) não existem cá. Os PPR são oferecidos por bancos, seguradoras e gestoras. Para os pormenores do regime, vê o tema <b>PPR e benefícios fiscais</b> no módulo de impostos, <b>PPR ou investir por conta própria</b> no módulo de planeamento e <b>Reforma e Segurança Social</b> para perceber o contexto da reforma.'},
    {t:'note',id:'n2',pending:true,x:'Confirma no Portal das Finanças os limites do ano em que fores aplicar. A dedução só te ajuda se tiveres coleta suficiente para a aproveitar.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Um PPR é um regime fiscal aplicado a um fundo, a um seguro ou a outro formato.',
      'Deduzes 20% do valor aplicado, com limites de 400, 350 ou 300 € conforme a idade.',
      'Só levantas sem penalização depois de 5 anos e em situações previstas na lei.',
      'Fora disso, devolves a dedução com 10% a mais por cada ano ou fração.',
      'Os custos do produto podem pesar mais do que o benefício: compara sempre.']},
    {t:'fazve',id:'q1',ensina:['p2','c1'],q:'Tens 40 anos e aplicas 2 000 € num PPR. Qual é a dedução no IRS, em euros? (20% do valor, com o limite da tua idade.)',unit:'€',answer:350,tol:.01,why:'20% de 2 000 € seria 400 €, mas o limite para quem tem entre 35 e 50 anos é 350 €. A dedução é de 350 €.'},
    {t:'decide',id:'q2',ensina:['p4','p5'],label:'Decide',q:'Aplicaste num PPR há 2 anos e precisas do dinheiro para uma obra. O que acontece ao benefício fiscal se levantares?',o:['Nada, podes levantar sempre','Ganhas um prémio extra','Perdes o benefício e as deduções são acrescidas à coleta, com uma majoração de 10% por ano ou fração'],c:2,why:'Antes dos 5 anos e fora das situações previstas, o benefício é anulado e o imposto poupado volta a ser acrescido, com majoração.'},
    {t:'fazve',id:'q3',ensina:['p3','c1'],q:'Tens 52 anos. Quanto precisas de aplicar num ano para chegar à dedução máxima, em euros?',unit:'€',answer:300/0.2,tol:.01,why:'O limite para quem tem mais de 50 anos é 300 €, e a dedução é de 20% do valor aplicado: 300 ÷ 0,20 = 1 500 €.'},
    {t:'erro',id:'q4',ensina:['p1','p4','p7'],label:'Encontra o erro',q:'Uma destas frases sobre o PPR está errada. Qual?',o:['Pode ser um fundo, um seguro ou outro formato','Dá uma dedução de 20% do valor aplicado, com limite','O capital está sempre garantido','Os custos de gestão podem pesar bastante no resultado'],c:2,why:'A garantia de capital depende do produto. Um PPR de ações, por exemplo, pode perder valor.'}
  ], src:[_prod_ebf21,{l:'Portal das Finanças: IRS, deduções e benefícios fiscais (folheto 2025)',u:'https://info.portaldasfinancas.gov.pt/pt/apoio_contribuinte/Folhetos_informativos/Documents/IRS_deducoes_2025.pdf'},_prod_ref] },

{ id:'seguros-capitalizacao', topic:'produtos', o:11, title:'Seguros de capitalização e unit-linked', mins:7,
  lead:'São produtos de poupança vendidos por seguradoras, muitas vezes ao balcão do banco. Parecem simples, mas em muitos casos o risco do investimento é teu, os custos vêm em camadas e as regras fiscais têm pormenores. Convém saber o que se compra.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Imagina uma caixa de presente. Por fora, tem o laço de uma seguradora; por dentro, pode ter um simples produto de poupança com juros definidos, ou fundos de investimento que sobem e descem. O que muda o risco não é o laço, é o que está dentro. Um <b>seguro de capitalização</b> é essa caixa: entregas dinheiro à seguradora, e ela investe-o e devolve-o mais tarde, com ou sem rendimento garantido.'},
    {t:'h',id:'h1',x:'O que são e quem corre o risco'},
    {t:'p',id:'p1',x:'A ASF, a autoridade que supervisiona os seguros em Portugal, explica que as operações de capitalização não estão ligadas à morte ou à sobrevivência da pessoa: o risco que a seguradora cobre é apenas financeiro, o de investimento. Nos produtos <b>ligados a fundos de investimento</b>, os chamados <b>unit-linked</b>, o valor do seguro varia com o valor das unidades de um ou vários fundos, e o risco do investimento é assumido, ainda que só em parte, pelo tomador do seguro, que és tu. O resultado pode ser nulo, e o dinheiro investido pode perder-se, a não ser que haja uma cláusula de garantia de capital ou de rendimento mínimo.'},
    {t:'cmp',id:'c1',head:['','Capitalização com capital garantido','Unit-linked'],rows:[
      ['Quem suporta o risco do investimento','A seguradora, até ao que for garantido','Tu, em grande parte'],
      ['Rendimento','Definido à partida ou com mínimo','Depende dos fundos escolhidos'],
      ['O que podes perder','Em princípio, nada do capital garantido (se a seguradora cumprir)','Parte ou todo o capital investido'],
      ['Garantia de depósitos','Não se aplica: não é um depósito','Não se aplica'],
      ['Liquidez','Depende do contrato: resgate com ou sem penalização','Idem; confirma regras e prazos'],
      ['Onde vês os custos','No prospeto e na ficha de informação do produto','No seguro e nos fundos internos']],
      cap:'Classificação geral, a partir da ASF. Cada contrato tem as suas condições: lê a ficha de informação e as condições gerais.'},
    {t:'h',id:'h2',x:'Os custos vêm em camadas'},
    {t:'p',id:'p2',x:'Num seguro unit-linked podes pagar a comissão de gestão do seguro, os custos dos fundos que estão lá dentro (o TER), comissões de subscrição ou resgate e, se houver componente de proteção, o custo do seguro de vida. Cada camada parece pequena, mas somam-se.'},
    {t:'p',id:'p3',x:`Um exemplo com valores ilustrativos: aplicas ${_e(200)} por mês durante 20 anos, com retorno de 5% antes de custos. Com custos totais de 2,2% ao ano (seguro mais fundos), acabas com ${_e(_c('fees',{ini:0,men:200,rate:5,ter:2.2,ano:20})[1])}. Com um ETF de custo 0,2%, ficarias com ${_e(_c('fees',{ini:0,men:200,rate:5,ter:0.2,ano:20})[1])}. A diferença é de ${_e(_c('fees',{ini:0,men:200,rate:5,ter:0.2,ano:20})[1]-_c('fees',{ini:0,men:200,rate:5,ter:2.2,ano:20})[1])}. O seguro pode ter vantagens que justifiquem parte do custo, mas é preciso saber qual e se a queres.`},
    {t:'h',id:'h3',x:'O imposto: o que a AT diz sobre seguros de vida'},
    {t:'p',id:'p4',x:'Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), os rendimentos de seguros de vida são rendimentos de capitais, apurados pela diferença positiva entre o que recebes (resgate, adiantamento ou vencimento) e os prémios pagos. Estão sujeitos a retenção na fonte de 28% a título definitivo, com opção pelo englobamento. Há, porém, uma redução: se as entregas feitas na primeira parte da vigência do contrato representarem pelo menos 35% do total, só 4/5 do rendimento é tributado se o resgate ocorrer entre os 5 e os 8 anos, e só 2/5 se ocorrer depois de 8 anos.'},
    {t:'cmp',id:'c2',head:['Quando resgatas','Parte do ganho tributada','Imposto sobre um ganho de 2 000 € (28%)'],rows:[
      ['Antes de 5 anos','Todo o ganho',_e(2000*0.28)],
      ['Entre 5 e 8 anos','4/5 do ganho',_e(2000*0.8*0.28)],
      ['Depois de 8 anos','2/5 do ganho',_e(2000*0.4*0.28)]],
      cap:'Exemplo com um ganho de 2 000 € e as condições do guia da AT. A taxa efetiva baixa de 28% para 22,4% e para 11,2% do ganho.'},
    {t:'note',id:'n1',pending:true,x:'O guia da AT fala em «seguros de vida». Não confirmámos em fonte oficial se um seguro de capitalização ou um unit-linked concreto segue exatamente esta regra, nem como se tratam as componentes de morte, os beneficiários e o imposto do selo. Pede sempre a ficha fiscal do produto antes de subscrever.'},
    {t:'h',id:'h4',x:'Um caso real: quando a seguradora aparece no noticiário'},
    {t:'p',id:'p5',x:'Em 2008, a AIG, uma das maiores seguradoras do mundo, só não foi à falência porque o Estado americano a salvou. O caso mostra que uma garantia de capital dada por uma seguradora vale o que vale a seguradora, e que por isso o risco de crédito do emissor conta mesmo em produtos «seguros». Em Portugal, a supervisão é feita pela ASF, mas isso não equivale a uma garantia do dinheiro, como a do Fundo de Garantia de Depósitos para os depósitos.'},
    {t:'h',id:'h5',x:'Perguntas a fazer antes de assinar'},
    {t:'ul',id:'u1',x:[
      'O capital está garantido? Por quem, até quando e em que condições?',
      'Quais são todos os custos, por camada, e quanto pesam por ano?',
      'Posso resgatar quando quiser? Há penalização e como se calcula?',
      'O que está dentro: que fundos, que ativos, que risco?',
      'Qual é a ficha fiscal e como vai ser tributado o meu resgate?',
      'Se a seguradora tiver problemas, o que acontece ao meu dinheiro?']},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Subscrever um «seguro de poupança» pensando que é um depósito.',
      'Não ler os custos e descobrir depois que parte do rendimento ficou nas comissões.',
      'Achar que a garantia de depósitos protege o dinheiro de um seguro.',
      'Resgatar antes dos 5 anos sem saber que perdes a redução fiscal.',
      'Assinar por insistência do balcão sem comparar com depósitos ou ETFs.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Em Portugal, estes produtos são vendidos por seguradoras e muitas vezes pelos bancos que são seus mediadores. Quem supervisiona a seguradora é a ASF, e a informação ao cliente, incluindo o documento de informação fundamental (KID), deve estar disponível antes da subscrição. Para o imposto, vê o tema <b>Englobamento: quando compensa</b>. Para comparar com alternativas, vê <b>Depósitos a prazo</b>, <b>Fundos de investimento</b> e <b>PPR: poupança com benefício fiscal</b>. Os PPR também podem existir em formato de seguro.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Uma operação de capitalização cobre risco financeiro, não morte ou sobrevivência, segundo a ASF.',
      'Num unit-linked o risco do investimento é, em grande parte, teu; a garantia de capital é a exceção.',
      'Não é um depósito: o Fundo de Garantia de Depósitos não se aplica.',
      'Os custos vêm em camadas (seguro, fundos, comissões) e pesam durante anos.',
      'A AT indica redução do imposto em seguros de vida resgatados depois de 5 e depois de 8 anos, se cumpridas as condições.']},
    {t:'decide',id:'q1',ensina:['p1','c1'],label:'Decide',q:'Num seguro unit-linked sem cláusula de garantia, quem suporta o risco de o valor dos fundos descer?',o:['O tomador do seguro, que pode perder parte do capital','A seguradora, sempre','O Fundo de Garantia de Depósitos'],c:0,why:'Segundo a ASF, o risco do investimento é assumido, ainda que só em parte, pelo tomador. Só quando existe cláusula de garantia a seguradora cobre parte desse risco.'},
    {t:'fazve',id:'q2',ensina:['p4','c2'],q:'Resgatas, ao fim de 6 anos, um seguro de vida com um ganho de 2 000 €, e cumpres as condições da redução. Quanto pagas de imposto a 28%, em euros?',unit:'€',answer:Math.round(2000*0.8*0.28),tol:.02,why:'Entre 5 e 8 anos só 4/5 do ganho é tributado: 2 000 × 0,8 = 1 600 €. A 28%: 448 €.'},
    {t:'erro',id:'q3',ensina:['p1','c1','p5'],label:'Encontra o erro',q:'Uma destas frases sobre seguros de capitalização e unit-linked está errada. Qual?',o:['O risco de investimento pode ser, em parte, do tomador','A garantia de capital é a exceção nos unit-linked','O Fundo de Garantia de Depósitos protege o capital investido','Os custos podem vir em várias camadas'],c:2,why:'O Fundo de Garantia de Depósitos protege depósitos, não seguros nem fundos.'},
    {t:'decide',id:'q4',ensina:['p2','p3'],label:'Decide',q:'O balcão do banco propõe-te um unit-linked com custos totais de 2,2% ao ano, em vez de um ETF com custos de 0,2%. O que deves fazer?',o:['Aceitar, porque o seguro é sempre mais seguro','Comparar custos e o que o seguro dá de extra, e decidir com os números','Rejeitar sempre, porque todos os seguros são maus'],c:1,why:'A diferença de custos é grande ao longo de 20 anos. O seguro pode ter vantagens, mas só compensa se as quiseres e se perceberes o que pagas por elas.'}
  ], src:[_prod_asf,_prod_ref] },

{ id:'estruturados', topic:'produtos', o:12, title:'Produtos estruturados e depósitos indexados', mins:7,
  lead:'Prometem «capital garantido» e rendimento ligado à bolsa. São uma caixa fechada onde se mistura um empréstimo, uma aposta e custos escondidos. Aqui vês o que escondem e o que perguntar antes de assinar.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Pensa numa caixa fechada com dois compartimentos. Num está o teu capital, emprestado ao banco ou à entidade que emite o produto, que o devolve no fim. No outro está um bilhete de lotaria: se um índice de bolsa subir, recebes uma parte da subida, até um limite; se descer, o bilhete vale zero. Um <b>produto estruturado</b> é esta caixa: um empréstimo mais uma opção, empacotados num só produto.'},
    {t:'p',id:'p1',x:'O <b>depósito indexado</b> é a versão em forma de depósito: o capital é devolvido no vencimento e a remuneração depende da evolução de um índice ou de um cabaz de ações. O Banco de Portugal publica prospetos de depósitos indexados no Portal do Cliente Bancário, e classifica-os como «produto financeiro complexo». Nesses prospetos aparece a mesma estrutura: capital garantido na data de vencimento, remuneração variável e, em geral, sem possibilidade de mobilização antecipada.'},
    {t:'h',id:'h1',x:'Como funciona por dentro'},
    {t:'p',id:'p2',x:'Quando entregas 10 000 € por 5 anos, o emissor aplica a maior parte num instrumento que lhe devolve os 10 000 € no fim e usa a pequena parte que sobra para comprar a opção que paga o bónus ligado ao índice. É por isso que o capital é garantido: o primeiro compartimento garante o nominal. E é por isso que há sempre um teto: o dinheiro para a opção é pouco.'},
    {t:'p',id:'p3',x:`Vamos a um exemplo com valores de exemplo. Capital: ${_e(10000)}, prazo: 5 anos, participação de 60% na subida do índice, mínimo de 0% e teto de 25% no total. Se o índice subir 40%, a participação seria 24%, e recebes ${_e(10000*_prod_est(0.4))} de remuneração. Se subir 100%, o teto trava-te em ${_prod_pc(25,0)} (${_e(10000*0.25)}). Se descer, recebes o capital e nada mais.`},
    {t:'cmp',id:'c1',head:['O índice varia em 5 anos','Remuneração total (60% da subida, teto de 25%)','Taxa anual equivalente','Depósito a 2% brutos, 5 anos (para comparar)'],rows:[-0.2,0.1,0.4,1].map(v=>[_prod_pc(v*100,0),_prod_pc(_prod_est(v)*100,1),_prod_pc((Math.pow(1+_prod_est(v),1/5)-1)*100,2),_prod_pc((Math.pow(1.02,5)-1)*100,1)]),
      cap:'Valores de exemplo, sem impostos. A «taxa anual equivalente» é a que daria o mesmo resultado com juros compostos.'},
    {t:'p',id:'p4',x:`Repara no que o teto custa. Em 5 anos, o depósito a 2% brutos dá ${_prod_pc((Math.pow(1.02,5)-1)*100,1)}; o produto estruturado dá 0% se o índice descer, ${_prod_pc(_prod_est(0.1)*100,1)} se subir 10% e no máximo ${_prod_pc(25,0)}. Em cenários maus, o estruturado perde para o depósito; só em cenários bons ganha, e com limite.`},
    {t:'h',id:'h2',x:'O que costuma estar escondido'},
    {t:'ul',id:'u1',x:[
      '<b>Dividendos que não recebes.</b> Muitos produtos ligam-se a índices de preço, que não incluem os dividendos pagos pelas empresas. Se os dividendos do índice forem de cerca de 3% ao ano, em 5 anos deixas de ganhar cerca de 16% (valor de exemplo), que ficam com o emissor.',
      '<b>Teto e participação.</b> Só recebes uma parte da subida, e só até um limite.',
      '<b>Cálculo da subida.</b> Se for pela média dos últimos meses e não pelo valor final, o ganho pode ser menor.',
      '<b>Custos embutidos.</b> A margem do emissor não aparece como comissão, vem no preço do produto.',
      '<b>Risco do emissor.</b> A «garantia» de capital vale o que vale quem a dá.',
      '<b>Pouca liquidez.</b> Sair antes do fim pode implicar perdas ou nem ser possível.']},
    {t:'note',id:'n1',x:`Um exemplo do custo dos dividendos: um índice com dividendos de 3% ao ano rende ${_prod_pc((Math.pow(1.03,5)-1)*100,1)} só em dividendos em 5 anos, valor que um produto ligado ao índice de preço não te dá (valor de exemplo).`},
    {t:'h',id:'h3',x:'Depósito indexado, obrigação estruturada e certificado'},
    {t:'cmp',id:'c2',head:['','Depósito indexado','Obrigação estruturada ou certificado'],rows:[
      ['O que é','Um depósito com rendimento variável','Um título de dívida do emissor com rendimento ligado a um ativo'],
      ['Capital','Garantido no vencimento, se o banco cumprir','Depende do produto: pode ser garantido ou não'],
      ['Fundo de Garantia de Depósitos','Os prospetos indicam se se aplica','Não se aplica: não é um depósito'],
      ['Risco do emissor','Banco','Banco ou outra entidade'],
      ['Liquidez','Em geral sem mobilização antecipada','Pode vender-se, ao preço de mercado, se houver mercado']],
      cap:'Classificação geral: lê o prospeto e a ficha de informação do produto concreto.'},
    {t:'note',id:'n2',pending:true,x:'Os prospetos dos depósitos indexados que o Banco de Portugal divulga referem se o produto está coberto pelo Fundo de Garantia de Depósitos, mas não confirmámos o enquadramento em fonte oficial. Lê no prospeto do produto concreto.'},
    {t:'h',id:'h4',x:'Um caso real: Lehman e o papel comercial do BES'},
    {t:'p',id:'p5',x:'Em 2008, a falência do banco Lehman Brothers deixou sem valor produtos estruturados e certificados que tinha emitido ou garantido e que clientes de retalho de vários países tinham comprado como produtos «seguros». Em Portugal, em 2014, muitos clientes de retalho do Banco Espírito Santo tinham papel comercial (dívida de curto prazo) de empresas do grupo, vendido ao balcão, e perderam parte ou a totalidade do investimento quando o grupo colapsou. Os dois casos têm algo em comum: produtos que pareciam depósitos, sem a proteção dos depósitos, e a dependência de um emissor.'},
    {t:'h',id:'h5',x:'Perguntas a fazer antes de assinar'},
    {t:'ul',id:'u2',x:[
      'Quem é o emissor e qual é o seu risco de crédito?',
      'O capital é garantido? Em que data e por quem?',
      'Qual é a remuneração mínima? E o teto? Qual é a participação?',
      'O índice é de preço ou de retorno total (com dividendos)? Como se calcula a subida, pelo valor final ou por uma média?',
      'Quais são todos os custos, incluindo os que estão no preço?',
      'Posso sair antes? A que preço, e com que penalização?',
      'Como é tributado o rendimento? Qual é o documento de informação fundamental (KID) e o indicador de risco?']},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u3',x:[
      'Ler «capital garantido» e achar que não há risco: a garantia depende do emissor e só vale no vencimento.',
      'Ignorar o teto e o facto de os dividendos não contarem.',
      'Comparar o melhor cenário do produto com o pior do depósito.',
      'Precisar do dinheiro antes do vencimento e descobrir que não é possível.',
      'Assinar sem ler o prospeto, por confiança no balcão.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Estes produtos são vendidos por bancos em Portugal, e os depósitos indexados constam do Portal do Cliente Bancário. Segundo o guia fiscal da AT (outubro de 2023, consultado em 17/11/2026), a remuneração de certificados que garantam um valor mínimo superior ao da subscrição é rendimento de capitais, com retenção de 28% a título definitivo; os ganhos de certificados ligados ao valor de um ativo são mais-valias à taxa de 28%, com opção de englobamento. Os juros de depósitos sofrem retenção de 28%; o tratamento da remuneração variável de um depósito indexado deve constar da ficha do produto. Para as regras de proteção, vê <b>Quem protege o teu dinheiro se o banco falir</b> e <b>Sistema de Indemnização aos Investidores</b>, e para os esquemas fraudulentos, <b>Burlas e a lista da CMVM</b>.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u4',x:[
      'Um produto estruturado é um empréstimo mais uma opção; o capital volta no fim, o bónus depende de um índice.',
      'O depósito indexado é classificado como produto financeiro complexo pelo Banco de Portugal.',
      'O teto, a participação e os dividendos que não recebes diminuem o ganho.',
      'A garantia de capital vale o que vale o emissor, e só no vencimento.',
      'Antes de assinar, pergunta pelo emissor, teto, custos, saída antecipada e KID.']},
    {t:'fazve',id:'q1',ensina:['p3','c1'],q:'Um produto estruturado dá 60% da subida do índice, com teto de 25% no total. O índice sobe 30% em 5 anos. Qual é a remuneração total, em %?',unit:'%',answer:Number((_prod_est(0.3)*100).toFixed(1)),tol:.02,why:'60% de 30% = 18%, abaixo do teto de 25%. A remuneração é de 18%.'},
    {t:'decide',id:'q2',ensina:['p1','c2'],label:'Decide',q:'Um depósito indexado diz «capital garantido». O que isso quer dizer?',o:['Que a remuneração também está garantida','Que o produto pode ser levantado a qualquer momento','Que o capital é devolvido no vencimento, se o emissor cumprir, mas a remuneração pode ser baixa ou nula'],c:2,why:'A garantia refere-se ao capital na data de vencimento. A remuneração depende do índice e pode ser zero, e o capital depende do banco emissor.'},
    {t:'erro',id:'q3',ensina:['u1','p4','n1'],label:'Encontra o erro',q:'Uma destas frases sobre produtos estruturados está errada. Qual?',o:['O teto limita o ganho máximo','Os dividendos do índice de preço não entram na remuneração','Se o índice descer, recebes sempre mais do que num depósito','O risco do emissor existe mesmo com capital garantido'],c:2,why:'Se o índice descer, a remuneração é normalmente zero, o que é menos do que um depósito, que paga juro de qualquer maneira.'},
    {t:'decide',id:'q4',ensina:['p5','c2','u2'],label:'Decide',q:'O balcão do banco propõe-te um produto «seguro» com remuneração ligada à bolsa. Qual é a primeira coisa a perguntar?',o:['Quem é o emissor e o que acontece se falhar','Qual é a rentabilidade do ano passado','Qual é a cor do documento'],c:0,why:'O produto vale o que vale o emissor, e a proteção de um depósito pode não se aplicar. Perguntar pelo emissor e pelas condições é o primeiro passo.'}
  ], src:[_prod_bpdep,_prod_ref] }
);
const _prod_esma={l:'ESMA: medidas finais de intervenção sobre CFD e opções binárias (aplicáveis desde 1 de agosto de 2018)',u:'https://www.esma.europa.eu/press-news/esma-news/esma-adopts-final-product-intervention-measures-cfds-and-binary-options'};
const _prod_bdpcripto={l:'Banco de Portugal: Criptoativos (MiCA e supervisão)',u:'https://www.bportugal.pt/page/criptoativos'};

LRN.push(
{ id:'imobiliario', topic:'produtos', o:13, title:'Imobiliário e REITs', mins:6,
  lead:'Investir em imobiliário pode ser comprar uma casa para arrendar ou comprar uma fração de vários imóveis em bolsa. Os riscos e o esforço são muito diferentes, e a rentabilidade que se anuncia raramente é a que fica.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Ter uma casa arrendada é como ter uma pequena empresa com um único cliente: o negócio funciona enquanto o inquilino paga, e passas a ter obras, impostos e meses sem renda. Quem prefere não ser senhorio pode comprar uma fração de muitas «casas» através de um fundo ou de uma empresa cotada, e deixa a gestão para outros. Os dois caminhos chamam-se imobiliário, mas parecem-se pouco.'},
    {t:'cmp',id:'c1',head:['','Imóvel direto','Fundo ou REIT cotado'],rows:[
      ['Montante inicial','Elevado','Desde pequenas quantias'],
      ['Liquidez','Baixa: vender demora meses','Alta: vende-se em bolsa em segundos'],
      ['Diversificação','Um imóvel, uma localização','Muitos imóveis, vários países'],
      ['Trabalho','Obras, inquilinos, manutenção','Nenhum'],
      ['Preço','Só vês o valor quando vendes','Muda todos os dias, às vezes mais do que os imóveis']]},
    {t:'p',id:'p1',x:'Um <b>REIT</b> (<i>real estate investment trust</i>) é uma empresa que possui e gere imóveis que geram rendas e que, em muitos países, é obrigada a distribuir a maior parte do rendimento. Para um particular em Portugal, a forma mais acessível é um ETF UCITS que investe em imobiliário cotado: verifica na tua corretora o que está disponível.'},
    {t:'h',id:'h1',x:'A rentabilidade que se anuncia e a que fica'},
    {t:'p',id:'p2',x:`Uma casa de ${_e(200000)} arrendada por ${_e(800)} por mês rende ${_e(800*12)} por ano, ou seja, ${_prod_pc(800*12/200000*100)} do valor da casa. É a <b>rentabilidade bruta</b>. Mas dessa renda saem os custos. Com valores de exemplo (impostos locais, condomínio, seguro, manutenção e um mês sem inquilino por ano), digamos ${_e(2600)} por ano, ficam ${_e(800*12-2600)}, ou seja, ${_prod_pc((800*12-2600)/200000*100)}. E ainda falta o IRS sobre a renda.`},
    {t:'stat',id:'s1',v:800*12-2600,label:'o que fica por ano, antes de IRS, de uma casa de 200 000 € arrendada a 800 € por mês (valores de exemplo)'},
    {t:'note',id:'n1',pending:true,x:'Não confirmámos em fonte oficial nesta consulta o IRS sobre as rendas, o IMI nem o IMT na compra. Confirma sempre no Portal das Finanças antes de fazer as contas do teu caso.'},
    {t:'h',id:'h1b',x:'Que tipos de imobiliário há para investir'},
    {t:'cmp',id:'c1b',head:['Via','O que é','O que dá','Pontos fracos'],rows:[
      ['Arrendamento de longa duração','Casa ou apartamento arrendado a um inquilino','Renda mensal previsível','Meses sem inquilino, incumprimento, obras'],
      ['Alojamento local ou temporário','Arrendamento de curta duração a turistas','Rendas por noite mais altas','Mais trabalho, regras locais, procura sazonal'],
      ['Terrenos e obras','Comprar para construir ou revender','Ganho se o valor subir','Sem renda, licenças e prazos longos'],
      ['Fundos e REITs','Frações de carteiras de imóveis','Rendimento distribuído e liquidez','Preço oscila e há custos de gestão'],
      ['Plataformas de financiamento coletivo','Pequenas quantias em projetos imobiliários','Retornos prometidos em juros','Risco de perda total e pouca liquidez']],
      cap:'Classificação geral. Cada via tem regras próprias, que não confirmámos aqui em fonte oficial.'},
    {t:'p',id:'p2b',x:'Comprar e vender imóveis tem também custos de entrada e de saída: escritura, registos, impostos de transmissão, eventual comissão de mediação e tempo até encontrar comprador. Estes custos «fixos» são pesados no curto prazo, por isso o imobiliário direto só faz sentido com horizonte longo, de muitos anos. Em comparação, um ETF imobiliário compra-se e vende-se em bolsa pagando uma comissão pequena.'},
{t:'h',id:'h2',x:'O efeito do crédito'},
    {t:'p',id:'p3',x:`Muita gente compra imóveis com crédito. Se compras uma casa de ${_e(200000)} com ${_e(40000)} teus e ${_e(160000)} de empréstimo, e o preço desce 10%, a casa passa a valer ${_e(180000)}. Perdeste ${_e(20000)}, que são ${_prod_pc(20000/40000*100,0)} do dinheiro teu, e a dívida continua a ser de ${_e(160000)}. O crédito multiplica ganhos e perdas, como a alavancagem de que se fala no tema <b>Opções, CFD e alavancagem (riscos)</b>.`},
    {t:'h',id:'h3',x:'Fundos imobiliários, REITs e ETFs'},
    {t:'p',id:'p4',x:'Os fundos imobiliários investem em imóveis diretamente ou em empresas do setor. Existem fundos <b>abertos</b>, em que podes entrar e sair, e <b>fechados</b>, em que o dinheiro fica preso até ao fim do prazo ou só pode ser vendido a outro investidor. O preço de um fundo é, em regra, determinado por avaliações periódicas dos imóveis, e não minuto a minuto, o que dá a sensação de menor oscilação. Os REITs cotados, em bolsa, oscilam todos os dias, muitas vezes tanto como as ações.'},
    {t:'h',id:'h4',x:'Um caso real: 2008 e a crise na sombra do crédito'},
    {t:'p',id:'p5',x:'A crise financeira de 2008 começou no imobiliário americano: empréstimos concedidos a quem não os podia pagar, empacotados em produtos que se espalharam pelo sistema financeiro mundial. Quando os preços das casas desceram e os créditos falharam, caíram bancos e as empresas cotadas do setor perderam grande parte do valor. Na Europa do Sul, e em Portugal, a crise da dívida que se seguiu trouxe descidas de preços e anos de procura fraca. O caso mostra que o imobiliário não é «sempre seguro» e que a alavancagem torna as quedas muito mais dolorosas.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Contar só a renda bruta e esquecer impostos, obras, seguro e meses vazios.',
      'Comprar com crédito sem margem para uma queda de preços ou de rendas.',
      'Ter todo o património numa só casa, na mesma cidade onde vives e trabalhas.',
      'Confundir comprar casa para viver com investir: são decisões diferentes.',
      'Esperar liquidez: vender um imóvel demora meses e custa comissões.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p6',x:'Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), os rendimentos distribuídos por fundos de investimento imobiliário portugueses a residentes são tributados como rendimentos prediais, com retenção de 28% a título definitivo; o resgate também sofre retenção de 28%; e a venda das unidades de participação gera mais-valias de englobamento obrigatório, entrando só 50% do saldo positivo. Vê os temas <b>Comprar casa ou investir</b>, no módulo de planeamento, e <b>Englobamento: quando compensa</b>. Para REITs e ETFs imobiliários estrangeiros, segue-se o regime dos fundos não residentes (28% sobre distribuições e mais-valias, declarado no anexo J).'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'Imobiliário direto dá trabalho, é pouco líquido e concentra risco numa só casa.',
      'Fundos e REITs dão uma fração de muitos imóveis e liquidez, mas oscilam.',
      'A rentabilidade bruta engana: contam impostos, obras, seguros e meses sem renda.',
      'O crédito multiplica os ganhos e as perdas.',
      'Em Portugal, o regime fiscal varia conforme o veículo: confirma antes de decidir.']},
    {t:'decide',id:'q1',ensina:['c1','p1'],label:'Decide',q:'Tens uma pequena quantia e queres exposição ao imobiliário sem seres senhorio. O que se adequa melhor?',o:['Comprar um apartamento para arrendar','Um fundo ou ETF de imobiliário cotado','Esperar até ter dinheiro para uma casa inteira'],c:1,why:'Os veículos cotados dão-te uma fração de muitos imóveis com um montante pequeno e liquidez.'},
    {t:'erro',id:'q2',ensina:['c1','p4','p5'],label:'Encontra o erro',q:'Uma destas afirmações está errada. Qual?',o:['Um imóvel direto é pouco líquido','Um REIT cotado negoceia-se em bolsa','Imóveis nunca perdem valor','Um fundo imobiliário diversifica por vários imóveis'],c:2,why:'Os preços dos imóveis podem cair, tal como outros ativos, e a venda pode demorar.'},
    {t:'fazve',id:'q3',ensina:['p2'],q:'Uma casa de 200 000 € dá 9 600 € de renda por ano e tem 2 600 € de custos anuais. Qual é a rentabilidade líquida antes de IRS, em %?',unit:'%',answer:Number(((9600-2600)/200000*100).toFixed(2)),tol:.02,why:'(9 600 − 2 600) ÷ 200 000 = 3,5%. A rentabilidade bruta seria 4,8%.'},
    {t:'fazve',id:'q4',ensina:['p3'],q:'Compras uma casa de 200 000 € com 40 000 € teus e o resto em crédito. O preço desce 10%. Que percentagem do teu dinheiro perdeste?',unit:'%',answer:50,tol:.02,why:'10% de 200 000 € são 20 000 €. Sobre 40 000 € teus, perdeste 50%.'}
  ], src:[_prod_ref] },

{ id:'ouro', topic:'produtos', o:14, title:'Ouro e matérias-primas', mins:6,
  lead:'Ouro, petróleo, cobre e produtos agrícolas têm valor real, mas não pagam juros nem dividendos: só ganhas se o preço subir. Percebe porque é que isso muda tudo, e como se compram em Portugal.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Uma ação é como uma árvore de fruto: dá fruta (dividendos) e cresce. Uma obrigação é como uma renda: pagas hoje e recebes um pouco todos os anos. O ouro é uma pedra bonita num cofre: não dá fruta, não paga renda e, se a guardares, só vale mais amanhã se alguém a quiser comprar por mais. Isto não faz do ouro um mau produto, mas obriga a usá-lo para outra coisa.'},
    {t:'p',id:'p1',x:'O <b>ouro</b> é visto como reserva de valor em tempos de incerteza. Mas não gera rendimento: o retorno depende só do preço, que pode ficar estagnado durante anos. Outras <b>matérias-primas</b> (petróleo, gás, metais industriais, cereais) dependem da procura global e de choques de oferta, como uma guerra, uma seca ou uma decisão de um grupo de países produtores.'},
    {t:'h',id:'h1',x:'O que custa não render nada'},
    {t:'p',id:'p2',x:`Se um depósito te paga 2,5% por ano, quem escolhe o ouro está a abdicar desses 2,5%. Em 10 anos, a 2,5% compostos, o depósito cresceria ${_prod_pc((Math.pow(1.025,10)-1)*100,1)}. Para que o ouro valha a pena apenas em comparação com esse depósito, o preço teria de subir pelo menos isso, sem contar custos de guardar ou de comprar. Esta é a conta do <b>custo de oportunidade</b> do ouro, e muda conforme as taxas de juro: quando os juros estão altos, abdicar deles pesa mais.`},
    {t:'h',id:'h1b',x:'O que faz o preço do ouro mexer'},
    {t:'p',id:'p2b',x:'O preço do ouro tende a reagir a quatro coisas. Primeiro, às <b>taxas de juro reais</b> (as taxas depois de descontar a inflação): quando são altas, o ouro perde atrativo, porque um depósito ou uma obrigação rendem. Segundo, ao <b>dólar</b>, porque o ouro cota-se em dólares, e a um dólar mais fraco corresponde, em geral, um ouro mais caro para quem tem outras moedas. Terceiro, à <b>procura de bancos centrais</b> e de investidores, que o compram como reserva. Quarto, ao <b>medo</b>: em crises, muita gente procura ativos que não dependem de nenhum devedor. Nenhum destes fatores é previsível com regularidade.'},
    {t:'p',id:'p2c',x:`O peso na carteira conta. Numa carteira de ${_e(10000)}, 5% em ouro são ${_e(500)}. Se o ouro cair 40%, perdes ${_e(200)}, ou seja ${_prod_pc(200/10000*100,0)} da carteira, o que a maioria das pessoas suporta. Com 40% em ouro, a mesma queda custaria ${_e(1600)}, ${_prod_pc(1600/10000*100,0)} da carteira, e uma espera longa para recuperar.`},
{t:'h',id:'h2',x:'Formas de ter ouro'},
    {t:'cmp',id:'c1',head:['','Barras e moedas','ETC ou ETF de ouro físico','Ações de mineiras','Futuros de ouro'],rows:[
      ['O que tens','O metal, em tua casa ou num cofre','Um título que acompanha o preço, garantido por metal guardado','Ações de empresas que extraem ouro','Um contrato sobre o preço futuro'],
      ['Custos','Prémio na compra, diferença de preços, seguro e cofre','TER anual','TER ou comissões, e custos da empresa','Margem e custos de renovação'],
      ['Para quem','Quem quer o objeto físico','A maioria dos particulares','Quem aceita risco de empresa','Profissionais'],
      ['Risco extra','Roubo, perda, autenticidade','Risco do emissor, em alguns casos','Mais volátil do que o ouro','Alavancagem']],
      cap:'Os ETCs («exchange traded commodities») são títulos negociados em bolsa que seguem o preço da matéria-prima; verifica sempre o prospeto e o KID.'},
    {t:'h',id:'h3',x:'Matérias-primas e o custo escondido dos futuros'},
    {t:'p',id:'p3',x:`Um produto de matérias-primas que não guarda o metal ou o petróleo compra futuros, que são contratos para uma data futura, e todos os meses renova-os. Se o preço do contrato mais distante for mais alto do que o do mais próximo (uma situação chamada <b>contango</b>), cada renovação custa dinheiro. Com um contango de 0,25% ao mês, o custo é cerca de ${_prod_pc((Math.pow(1.0025,12)-1)*100,1)} por ano, que se soma ao TER. Por isso, o produto pode perder dinheiro mesmo quando o preço da matéria-prima ficou quase igual.`},
    {t:'h',id:'h4',x:'Um caso real: os anos 70 e a espera de vinte anos'},
    {t:'p',id:'p4',x:'Nos anos 70, com a inflação alta, o fim do padrão-ouro e choques no preço do petróleo, o ouro subiu muito até ao máximo de 1980. Depois caiu e levou mais de duas décadas a regressar a esse nível em termos nominais. Quem comprou em 1980 esperou mais de vinte anos para recuperar o dinheiro, e, descontada a inflação, esperou ainda mais. O mesmo ouro que protegeu muita gente em certos períodos fez outros esperar décadas. Isto mostra o ouro como diversificador, não como garantia.'},
    {t:'w',id:'w1',w:'calc',c:'drawdown'},
    {t:'p',id:'p5',x:`A calculadora mostra a regra da recuperação: se um ativo cai 40%, precisa de subir ${_prod_pc(_c('drawdown',{val:10000,q:40})[1])} para voltar ao ponto de partida. Quem compra ouro (ou qualquer ativo sem rendimento) depois de uma subida forte arrisca-se a uma espera longa.`},
    {t:'p',id:'p6',x:'Em carteira, o ouro costuma ser usado em pequena percentagem, como diversificador, porque tende a comportar-se de forma diferente das ações. Isso não garante que suba quando as ações caem.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u1',x:[
      'Comprar ouro como «proteção» e pôr nele uma fatia grande do património.',
      'Esquecer os custos de guardar, segurar e vender o metal físico.',
      'Comprar um produto de matérias-primas sem perceber o custo dos futuros.',
      'Comprar em momentos de euforia, depois de subidas fortes e notícias de «recordes».',
      'Comprar barras a quem não conheces, sem certificado.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Quase ninguém compra o metal em barra. Os particulares usam produtos cotados que acompanham o preço, como <b>ETCs</b> e ETFs. Em Portugal, confirma na tua corretora o produto concreto, a moeda e o ISIN, e se tem o documento europeu exigido (o KID). Os produtos americanos de ouro não se compram cá, mas existem equivalentes europeus.'},
    {t:'note',id:'n1',pending:true,x:'Não confirmámos em fonte oficial a tributação em IRS de ETCs de ouro, de ouro físico e de ETFs de matérias-primas. Antes de comprar, pergunta à corretora como são tratados e consulta o Portal das Finanças. Para o regime geral das mais-valias, vê o tema <b>Mais-valias: quanto imposto pagas ao vender</b>.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u2',x:[
      'O ouro não paga juros nem dividendos: o ganho vem só do preço.',
      'O custo de oportunidade conta: abdicas do rendimento que um depósito ou uma obrigação dariam.',
      'A forma de ter ouro muda os custos e os riscos: físico, ETC/ETF, mineiras ou futuros.',
      'Produtos com futuros podem perder valor por causa do contango.',
      'Serve como pequena parte da carteira, para diversificar, não como garantia.']},
    {t:'decide',id:'q1',ensina:['p1','p2'],label:'Decide',q:'Em que difere o ouro de uma ação ou obrigação em termos de rendimento?',o:['Paga dividendos todos os anos','Paga mais do que as obrigações','Não paga juros nem dividendos: o ganho vem só da variação do preço'],c:2,why:'O ouro não gera rendimento próprio. O retorno depende exclusivamente do preço de venda.'},
    {t:'decide',id:'q2',ensina:['p7','c1'],label:'Decide',q:'Como é que um particular em Portugal costuma ganhar exposição ao ouro?',o:['Através de um ETC ou ETF cotado, disponível na corretora','Comprando barras em casa e vendendo ao banco','Comprando ações de uma empresa chamada Ouro'],c:0,why:'Os produtos cotados são a via mais simples e líquida; a disponibilidade concreta depende da corretora.'},
    {t:'fazve',id:'q3',ensina:['p5','w1'],q:'Um produto de matérias-primas cai 40%. Quanto tem de subir, em %, para recuperar? (Arredonda às unidades.)',unit:'%',answer:Math.round(_c('drawdown',{val:10000,q:40})[1]),tol:.02,why:'Se 100 desce para 60, para voltar a 100 tem de subir 40 ÷ 60 = 66,7%. A recuperação exige sempre mais do que a queda.'},
    {t:'erro',id:'q4',ensina:['p3','h4','p4'],label:'Encontra o erro',q:'Uma destas frases está errada. Qual?',o:['O ouro não paga juros nem dividendos','Os futuros podem ter custos de renovação','O ouro sobe sempre quando as ações caem','O ouro pode demorar anos a recuperar de um máximo'],c:2,why:'O ouro pode comportar-se de forma diferente das ações, mas não há garantia de que suba quando elas caem.'}
  ], src:[_prod_ref] },

{ id:'cripto', topic:'produtos', o:15, title:'Criptoativos', mins:6,
  lead:'Bitcoin, Ethereum e outras criptomoedas são ativos digitais sem país nem banco central por trás. Têm potencial e riscos muito acima da média, e Portugal tem regras próprias para os impostos.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Pensa num caderno de registos que milhares de computadores guardam em simultâneo, e que ninguém pode alterar sozinho. Cada linha diz quem transferiu o quê a quem. É a ideia da <b>blockchain</b> (cadeia de blocos). Um criptoativo é um valor que existe nesse caderno: não está numa conta bancária, está registado na rede, e quem tiver a chave certa pode movê-lo.'},
    {t:'p',id:'p1',x:'Um criptoativo não gera juros nem dividendos por si só, e o preço depende da procura. Variações de dezenas de por cento em semanas são normais, e já houve quedas de 70% ou mais.'},
    {t:'h',id:'h1',x:'Os tipos mais comuns'},
    {t:'cmp',id:'c1',head:['Tipo','O que é','Risco principal'],rows:[
      ['Bitcoin','A primeira e maior criptomoeda, com oferta limitada','Preço muito volátil'],
      ['Ethereum e outras (altcoins)','Redes com funções adicionais, como contratos automáticos','Volatilidade e risco de a rede ou o projeto falhar'],
      ['Stablecoins','Tokens que tentam acompanhar o preço de uma moeda, como o euro ou o dólar','Perder a ligação à moeda; risco do emissor'],
      ['Tokens e «memecoins»','Moedas criadas por projetos pequenos ou por moda','Podem valer zero de um dia para o outro; muitas são burlas']],
      cap:'Classificação geral.'},
    {t:'h',id:'h1b',x:'Como se compram e o que custam'},
    {t:'p',id:'p1b',x:'Os criptoativos compram-se em plataformas de negociação, que te pedem a identificação (como num banco), um IBAN para depositar euros e cobram comissões. Há comissões por operação, uma diferença entre o preço de compra e de venda (o spread), custos de levantamento e, quando transferes para outra carteira, uma taxa paga à rede. Cada plataforma mostra estes custos de forma diferente, por isso convém somá-los antes de comparar.'},
    {t:'p',id:'p1c',x:'O <b>Bitcoin</b> foi desenhado com uma oferta limitada a 21 milhões de unidades, e muitos defensores usam essa escassez como argumento. Mas ser escasso não faz um ativo valioso: o preço depende de haver quem o queira comprar. Já o <b>staking</b> é uma forma de «bloquear» criptoativos numa rede para a ajudar a funcionar, em troca de uma recompensa, e tem os seus próprios riscos, como o de ficar sem acesso ao dinheiro durante um período.'},
{t:'h',id:'h2',x:'Onde fica guardado o teu dinheiro'},
    {t:'ul',id:'u1',x:[
      'Não são <b>depósitos</b>: a garantia de depósitos não se aplica.',
      'Se guardas numa plataforma, confias na plataforma: se falhar ou for burla, o dinheiro pode perder-se.',
      'Se guardas numa carteira pessoal, tens a chave privada: se a perderes, perdes o acesso para sempre.',
      'Muitas burlas usam criptomoedas: promessas de retornos garantidos são sinal de alarme.',
      'Mesmo para quem acredita no ativo, faz sentido que seja uma <b>pequena parte</b> do património, que aceitas perder.']},
    {t:'h',id:'h3',x:'Quanto pesa na carteira'},
    {t:'p',id:'p2',x:`Imagina uma carteira de ${_e(20000)}. Se puseres 5% em criptoativos, ou seja ${_e(1000)}, e eles caírem 70%, perdes ${_e(700)}, que são ${_prod_pc(700/20000*100)} da carteira. Se tivesses posto 50%, ou seja ${_e(10000)}, perderias ${_e(7000)}, ${_prod_pc(7000/20000*100,0)} da carteira. A percentagem que escolhes mede a dor que aceitas, não a esperança de ganho.`},
    {t:'w',id:'w1',w:'calc',c:'drawdown'},
    {t:'h',id:'h4',x:'Um caso real: 2022, Terra e FTX'},
    {t:'p',id:'p3',x:'Em maio de 2022, uma stablecoin chamada TerraUSD perdeu a ligação ao dólar e arrastou a moeda a ela associada para perto de zero, apagando em dias uma enorme quantidade de valor. Em novembro do mesmo ano, a FTX, uma das maiores plataformas de negociação do mundo, pediu falência, e muitos clientes ficaram sem acesso às suas contas. Os dois casos mostram os riscos que se repetem: produtos que prometem estabilidade sem a ter, e plataformas onde guardas o dinheiro dos outros em confiança.'},
    {t:'h',id:'h5',x:'Regulação'},
    {t:'p',id:'p4',x:'Na União Europeia, os criptoativos e quem presta serviços com eles passaram a estar abrangidos por um regulamento próprio, conhecido como <b>MiCA</b>. Em Portugal, o Banco de Portugal supervisiona os prestadores de serviços de criptoativos e mantém um registo, e a CMVM supervisiona outras partes do regime, como o abuso de mercado. Estar autorizado não quer dizer que o produto seja seguro: quer dizer que a entidade cumpre regras, e que existe uma lista para confirmar quem é quem. Segundo o Banco de Portugal, convém verificar o registo da entidade antes de lhe entregar dinheiro.'},
    {t:'h',id:'h5b',x:'Perguntas antes de comprar'},
    {t:'ul',id:'u1b',x:[
      'A entidade está autorizada ou registada, e consigo confirmá-lo numa lista oficial?',
      'Quanto me custa comprar, guardar, transferir e vender, tudo somado?',
      'Se a plataforma falhar, o que acontece ao meu dinheiro?',
      'Perdi as chaves ou as palavras de recuperação: consigo voltar a ter acesso?',
      'Se este dinheiro perder 70%, a minha vida muda?']},
    {t:'h',id:'h6',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Investir porque «toda a gente está a ganhar» e vender com pânico na queda seguinte.',
      'Deixar o dinheiro numa plataforma que não verificaste ou que paga «juros» muito altos.',
      'Perder as palavras de recuperação da carteira, ou guardá-las num sítio inseguro.',
      'Clicar em ligações de «oportunidades» enviadas por desconhecidos ou por redes sociais.',
      'Esquecer que as vendas e trocas têm consequências fiscais.']},
    {t:'h',id:'h7',x:'Em Portugal'},
    {t:'p',id:'p5',x:'Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), as mais-valias da venda de criptoativos detidos há 365 dias ou mais não são tributadas; abaixo de 365 dias, são tributadas a 28% (e, nos criptoativos que sejam valores mobiliários, o englobamento é obrigatório para quem tem rendimento no último escalão). A troca de um criptoativo por outro não é tributada no momento, só quando se converte em dinheiro ou em bens. Os rendimentos de «staking» são rendimentos de capitais, tributados a 28%. Vê o tema <b>Criptoativos e IRS</b> no módulo de impostos, e <b>Esquemas e como nos enganam</b> e <b>Burlas e a lista da CMVM</b> para os sinais de alarme.'},
    {t:'note',id:'n1',pending:true,x:'O guia da AT é de outubro de 2023. Antes de declarares, confirma no Portal das Finanças as regras do ano em causa, incluindo os anexos G e G1 e o tratamento de criptoativos que sejam valores mobiliários.'},
    {t:'h',id:'h8',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Um criptoativo é um registo numa rede, sem banco central nem garantia de depósitos.',
      'O preço pode cair 70% ou mais; a percentagem que aplicas é a dor que aceitas.',
      'Plataformas e carteiras têm riscos diferentes: falha da plataforma, perda da chave, burla.',
      'No IRS, detenção de 365 dias ou mais não é tributada; abaixo disso, 28%.',
      'Retornos «garantidos» são um sinal de burla.']},
    {t:'decide',id:'q1',ensina:['p1','u1'],label:'Decide',q:'Um site promete 5% ao dia «garantidos» se depositares em criptomoedas. Como o classificas?',o:['Uma oportunidade rara','Um sinal claro de burla: nenhum retorno é garantido e este é irrealista','Um produto regulado, por usar criptomoedas'],c:1,why:'Retornos garantidos e muito altos são o sinal clássico de esquema fraudulento.'},
    {t:'erro',id:'q2',ensina:['u1'],label:'Encontra o erro',q:'Uma destas frases sobre criptoativos está errada. Qual?',o:['O preço pode variar dezenas de por cento em semanas','Não são depósitos bancários','O dinheiro em criptoativos está sempre protegido pela garantia de depósitos','Perder a chave privada pode significar perder o acesso'],c:2,why:'A garantia de depósitos cobre depósitos bancários, não criptoativos.'},
    {t:'fazve',id:'q3',ensina:['p2','w1'],q:'Tens uma carteira de 20 000 € e pões 5% em criptoativos. Eles caem 70%. Quanto perdes da carteira total, em %?',unit:'%',answer:Number((700/20000*100).toFixed(2)),tol:.02,why:'5% de 20 000 € são 1 000 €. 70% de 1 000 € são 700 €, que são 3,5% da carteira.'},
    {t:'decide',id:'q4',ensina:['p5'],label:'Decide',q:'Compraste um criptoativo há 400 dias e vendes com lucro. Segundo o guia da AT, como é tributado em Portugal, em regra?',o:['A 28%','A 50%','Não é tributado, por teres detido 365 dias ou mais'],c:2,why:'As mais-valias de criptoativos detidos há 365 dias ou mais não são tributadas. Abaixo disso, a taxa é de 28%.'}
  ], src:[_prod_ref,_prod_bdpcripto] },

{ id:'derivados', topic:'produtos', o:16, title:'Opções, CFD e alavancagem (riscos)', mins:7,
  lead:'Produtos que permitem apostar com dinheiro emprestado ou com direitos sobre um preço futuro. Podem multiplicar ganhos e perdas, e em alguns casos perde-se mais do que o investido. Convém perceber porquê antes de lhes chegar perto.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Imagina uma alavanca. Com um pequeno esforço, levantas um grande peso. Mas o mesmo mecanismo faz o peso descer depressa se escorregares. <b>Alavancagem</b> é investir mais do que o dinheiro que tens, com dinheiro emprestado ou implícito no produto. Com uma alavancagem de 10 para 1, uma subida de 5% dá 50% de ganho, mas uma queda de 5% dá −50%, e uma queda de 10% apaga tudo.'},
    {t:'h',id:'h1',x:'CFD: apostar sem possuir'},
    {t:'p',id:'p1',x:'Um <b>CFD</b> (contrato por diferença) é uma aposta sobre a variação de um preço, sem possuir o ativo, normalmente com alavancagem. Ganhas ou perdes a diferença entre o preço de abertura e o de fecho, multiplicada pela dimensão da posição. Pagas uma margem (um depósito de garantia) e o resto é emprestado pela corretora, que cobra juros por cada dia em que a posição fica aberta.'},
    {t:'p',id:'p2',x:`Em 2018, a ESMA, a autoridade europeia dos mercados, impôs limites para clientes de retalho, e mais tarde recordou que as medidas continuam a aplicar-se: alavancagem máxima de 30 para 1 em pares de moedas principais, 20 para 1 em pares secundários, ouro e índices principais, 10 para 1 em outras matérias-primas e índices secundários, 5 para 1 em ações e 2 para 1 em criptoativos. Obriga também a fechar posições quando a margem desce a 50% do mínimo exigido, a proteger o cliente de saldo negativo e a mostrar o aviso de que a maior parte dos clientes de retalho perde dinheiro (verificado em 17/11/2026).`},
    {t:'cmp',id:'c1',head:['Ativo subjacente','Alavancagem máxima para retalho','Variação contrária que apaga a margem inicial'],rows:[['Pares de moedas principais','30 para 1',_prod_pc(100/30)],['Ouro e índices principais','20 para 1',_prod_pc(100/20)],['Outras matérias-primas','10 para 1',_prod_pc(100/10)],['Ações','5 para 1',_prod_pc(100/5)],['Criptoativos','2 para 1',_prod_pc(100/2)]],
      cap:'Limites da ESMA para clientes de retalho (desde 1 de agosto de 2018). A última coluna é 100% ÷ alavancagem.'},
    {t:'p',id:'p3',x:`Um exemplo de uma ação com alavancagem de 5 para 1: depositas ${_e(1000)} de margem e abres uma posição de ${_e(5000)}. Se a ação cair 10%, perdes ${_e(500)}, metade da margem, e a corretora é obrigada a fechar a posição, porque a margem chegou a 50% do mínimo. Se caísse 20%, perderias os ${_e(1000)}, a totalidade. Com ações sem alavancagem, uma queda de 20% custaria 20% do dinheiro; aqui custa 100%.`},
    {t:'h',id:'h2',x:'Opções: o direito, não a obrigação'},
    {t:'p',id:'p4',x:`As <b>opções</b> dão o direito, não a obrigação, de comprar (<i>call</i>) ou vender (<i>put</i>) a um preço fixo até uma data. Pagas um <b>prémio</b>, que é o preço do direito. Um exemplo: uma ação vale ${_e(100)}; compras uma <i>call</i> com preço de exercício de ${_e(105)} e prémio de ${_e(3)} por ação, para 100 ações. Pagaste ${_e(300)}. Se no vencimento a ação valer ${_e(90)} ou ${_e(105)}, não vale a pena exercer e perdes os ${_e(300)}. Se valer ${_e(115)}, ganhas (115 − 105 − 3) × 100 = ${_e(700)}. O ponto em que começas a ganhar é ${_e(108)}.`},
    {t:'p',id:'p5',x:'Quem <b>compra</b> a opção arrisca no máximo o prémio. Quem a <b>vende</b> recebe o prémio, mas fica obrigado a cumprir, e pode perder muito mais: no caso de uma <i>call</i> vendida sem cobertura, a perda é, em teoria, ilimitada. As opções têm prazo: o tempo desgasta o valor, mesmo que o preço do ativo fique igual.'},
    {t:'h',id:'h3',x:'Futuros, margem e produtos de aposta curta'},
    {t:'ul',id:'u1',x:[
      '<b>Futuros e margem</b>: exigem depósitos de garantia e podem gerar chamadas de margem, em que és obrigado a pôr mais dinheiro.',
      '<b>Warrants e turbos</b>: títulos que dão direito sobre um ativo, com alavancagem incorporada e prazo curto.',
      '<b>ETFs alavancados e inversos</b>: procuram 2 ou 3 vezes o retorno diário do índice (ou o contrário), recalculados todos os dias.']},
    {t:'p',id:'p6',x:`Os ETFs alavancados têm uma armadilha. Um ETF 2x segue o dobro da variação <i>diária</i>. Se o índice subir 10% e depois descer 10%, acaba 1% abaixo (1,10 × 0,90 = ${_prod_n(1.1*0.9,2)}). O ETF 2x sobe 20% e desce 20%: 1,20 × 0,80 = ${_prod_n(1.2*0.8,2)}, ou seja, 4% abaixo. Quanto mais o índice oscila para cima e para baixo, mais o ETF alavancado perde em relação ao dobro do retorno do índice a longo prazo. É o efeito da recomposição diária.`},
    {t:'h',id:'h4',x:'Um caso real: o dia em que o franco suíço disparou'},
    {t:'p',id:'p7',x:'Em 15 de janeiro de 2015, o banco central suíço deixou de defender o limite do franco suíço face ao euro, e a moeda subiu de forma brusca em minutos. Quem estava a apostar com alavancagem contra o franco viu a margem desaparecer e, em muitos casos, ficou a dever dinheiro à corretora. Algumas corretoras tiveram prejuízos tão grandes que faliram ou precisaram de ajuda. Episódios assim ajudam a perceber porque a regulação europeia passou a exigir proteção contra saldo negativo para clientes de retalho.'},
    {t:'h',id:'h5',x:'Os erros que mais custam'},
    {t:'ul',id:'u2',x:[
      'Achar que consegues «adivinhar» a direção do mercado e usar alavancagem para ganhar depressa.',
      'Ignorar o custo diário do financiamento nas posições que ficam abertas.',
      'Vender opções para «receber prémio» sem perceber que o risco pode ser muito maior do que o prémio.',
      'Comprar ETFs alavancados para guardar durante anos.',
      'Responder a uma chamada de margem pondo mais dinheiro para não fechar a perder.']},
    {t:'h',id:'h6',x:'Em Portugal'},
    {t:'p',id:'p8',x:'Os CFD são oferecidos por corretoras autorizadas e estão sujeitos às regras da ESMA para clientes de retalho, em vigor desde 1 de agosto de 2018. Segundo o guia fiscal da AT (edição de outubro de 2023, consultada em 17/11/2026), o saldo anual positivo das operações com warrants é tributado a 28%, com opção de englobamento. Para os riscos de produtos que prometem retornos garantidos, vê o tema <b>Burlas e a lista da CMVM</b>. Para perceber porque não se deve mexer com o dinheiro que não se pode perder, vê o tema <b>Vieses que custam dinheiro</b>.'},
    {t:'note',id:'n1',pending:true,x:'Não confirmámos em fonte oficial a tributação em IRS dos CFD, das opções e dos futuros. Pergunta à corretora e consulta o Portal das Finanças antes de operar.'},
    {t:'note',id:'n2',x:'Para quem está a começar a aprender, o conselho é simples: fica longe destes produtos até perceberes bem os mais simples. Não são necessários para construir uma carteira sólida.'},
    {t:'h',id:'h7',x:'Em poucas palavras'},
    {t:'ul',id:'u3',x:[
      'Alavancagem multiplica ganhos e perdas; com 10 para 1, uma queda de 10% apaga tudo.',
      'A ESMA limita a alavancagem dos CFD para particulares de 30:1 a 2:1 e obriga a mostrar o aviso de risco.',
      'Quem compra uma opção arrisca o prémio; quem vende pode perder muito mais.',
      'ETFs alavancados recompõem-se todos os dias e perdem com a oscilação.',
      'Para quem começa, são produtos a evitar.']},
    {t:'fazve',id:'q1',ensina:['p0'],q:'Com uma alavancagem de 10 para 1, o ativo cai 5%. Quanto perdes do dinheiro que puseste, em %?',unit:'%',answer:50,tol:.02,why:'5% × 10 = 50%. Com alavancagem de 10, uma queda de 10% apaga a totalidade do capital.'},
    {t:'decide',id:'q2',ensina:['p0','p1','p2'],label:'Decide',q:'Por que razão os CFD com alavancagem são considerados de alto risco para quem está a começar?',o:['Porque as perdas também são multiplicadas e uma pequena variação pode apagar o capital','Porque são proibidos','Porque só se pode ganhar'],c:0,why:'A alavancagem multiplica ganhos e perdas. Uma pequena variação contrária pode consumir todo o dinheiro investido.'},
    {t:'fazve',id:'q3',ensina:['p4'],q:'Compras uma call sobre 100 ações com preço de exercício de 105 € e prémio de 3 € por ação. No vencimento a ação vale 115 €. Qual é o teu lucro, em euros?',unit:'€',answer:(115-105-3)*100,tol:.02,why:'Ganho por ação: 115 − 105 = 10 €. Menos o prémio de 3 €: 7 €. Para 100 ações: 700 €.'},
    {t:'erro',id:'q4',ensina:['p4','p5','p6'],label:'Encontra o erro',q:'Uma destas frases está errada. Qual?',o:['Quem compra uma opção arrisca, no máximo, o prémio pago','Quem vende uma call sem cobertura pode perder muito mais do que o prémio recebido','Um ETF alavancado 2x garante o dobro do retorno do índice a longo prazo','Um CFD com alavancagem pode apagar a margem com uma pequena variação do preço'],c:2,why:'O ETF 2x procura o dobro do retorno diário, e não o do longo prazo. Com oscilação, o resultado fica abaixo do dobro.'}
  ], src:[_prod_esma,_prod_ref] }
);

// ---- Crowdfunding e empréstimos P2P (acrescentada em 17/11/2026) ----
// Carteira de 10 empréstimos de 500 € a 9% durante 1 ano: resultado em € com d incumprimentos e taxa de recuperação r
const _cf_res=(d,r)=>(10-d)*500*1.09+d*500*r-5000;
const _cf_e=n=>(n>=0?'+':'−')+_e(Math.abs(n));
const _cf_ue={l:'EUR-Lex: Regulamento (UE) 2020/1503, prestadores europeus de serviços de financiamento colaborativo (art. 21.º, 22.º e 23.º; verificado em 17/11/2026)',u:'https://eur-lex.europa.eu/legal-content/PT/TXT/?uri=CELEX:32020R1503'};
const _cf_esma={l:'ESMA: registo de prestadores de serviços de financiamento colaborativo',u:'https://www.esma.europa.eu/'};

LRN.push(
{ id:'crowdfunding', topic:'produtos', o:13.5, title:'Crowdfunding e empréstimos P2P', mins:8,
  lead:'Em plataformas online podes emprestar dinheiro a empresas e a projetos imobiliários, ou comprar uma pequena parte de uma empresa que está a começar. As taxas anunciadas são altas porque o risco também é: aqui vês como funciona, que proteções a lei europeia te dá e porque é que um único incumprimento pode apagar o ganho de um ano.',
  blocks:[
    {t:'h',id:'h0',x:'Uma imagem para perceber'},
    {t:'p',id:'p0',x:'Quando pões dinheiro num depósito, o banco empresta-o a outros e fica com o risco: se um devedor não pagar, o problema é do banco. No <b>financiamento colaborativo</b> (crowdfunding) tiras o banco do meio. Uma plataforma online junta muitas pessoas que emprestam pequenas quantias a uma empresa ou a um projeto. A taxa é mais alta, mas <b>o risco de o devedor não pagar passa a ser teu</b>.'},
    {t:'h',id:'h1',x:'Os tipos que existem'},
    {t:'cmp',id:'c1',head:['Tipo','O que recebes','É investimento?','Risco principal'],rows:[
      ['Donativo ou recompensa','Nada, ou um produto ou brinde','Não','Perder o que deste'],
      ['Empréstimo a empresas (lending)','Juros e devolução do capital, em prestações ou no fim','Sim','A empresa não pagar'],
      ['Empréstimo a projetos imobiliários','Juros, muitas vezes só no fim da obra','Sim','A obra atrasar ou o promotor falhar'],
      ['Capital (equity)','Uma pequena parte da empresa','Sim','A empresa falir; não haver forma de vender'],
      ['Empréstimos a particulares (P2P ao consumo)','Juros de créditos pessoais','Sim','Incumprimento e risco da própria plataforma']],
      cap:'Classificação geral. Cada plataforma descreve o seu produto na ficha de informação.'},
    {t:'h',id:'h2',x:'Como funciona por dentro'},
    {t:'p',id:'p1',x:'A plataforma analisa o projeto, dá-lhe uma nota de risco e põe-no online com uma taxa e um prazo. Tu escolhes quanto pões em cada projeto. Quando o montante pedido é atingido, o dinheiro vai para o promotor, e a plataforma recebe e reparte os pagamentos. Ganha com comissões, cobradas ao promotor, a ti, ou aos dois.'},
    {t:'ul',id:'u1',x:[
      '<b>A taxa paga o risco.</b> Uma empresa que aceita pagar 9% ou 12% ao ano é, muitas vezes, uma empresa a quem o banco não emprestava, ou não nessas condições.',
      '<b>As garantias variam.</b> Pode haver hipoteca sobre o imóvel, aval dos sócios ou nada. Uma garantia só vale o que se conseguir recuperar, e recuperar demora.',
      '<b>Não há mercado para sair.</b> Em geral ficas até ao fim do prazo. Algumas plataformas têm mercado secundário, mas pode não haver comprador, ou só com desconto.',
      '<b>A plataforma também é um risco.</b> Se fechar, alguém tem de continuar a cobrar os empréstimos. A lei exige um plano para isso, mas na prática é lento.']},
    {t:'h',id:'h3',x:'Um exemplo com números'},
    {t:'p',id:'p2',x:`Valores de exemplo. Pões 5 000 € em 10 empréstimos de 500 €, a 9% ao ano, por um ano. Se todos pagarem, ganhas ${_e(_cf_res(0,0))}. Agora vê o que acontece quando um ou dois não pagam, e quanto se consegue recuperar das garantias:`},
    {t:'cmp',id:'c2',head:['Empréstimos que falham','Nada recuperado','Metade recuperada'],rows:[0,1,2].map(d=>[String(d),_cf_e(_cf_res(d,0)),_cf_e(_cf_res(d,0.5))]),
      cap:'10 empréstimos de 500 € a 9%, um ano, sem comissões nem impostos.'},
    {t:'p',id:'p3',x:`Com <b>um só</b> incumprimento sem recuperação, o ano fica negativo (${_cf_e(_cf_res(1,0))}). A taxa de 9% não é o que vais ganhar: é o máximo, se tudo correr bem. Por isso conta a <b>diversificação</b>: muitos empréstimos pequenos, em vários promotores, setores e plataformas. Com 10 empréstimos, cada incumprimento pesa 10% da carteira; com 50, pesa 2%.`},
    {t:'h',id:'h4',x:'O que a lei europeia te garante'},
    {t:'p',id:'p4',x:'Desde 10 de novembro de 2021, as plataformas de financiamento colaborativo a empresas na UE seguem o mesmo regulamento europeu, o <b>Regulamento (UE) 2020/1503</b>, e precisam de autorização do supervisor do seu país (em Portugal, a CMVM). Uma plataforma autorizada num país pode servir investidores dos outros. Para quem é investidor <b>não sofisticado</b> (a maioria das pessoas), o regulamento prevê:'},
    {t:'ul',id:'u2',x:[
      '<b>Teste de conhecimentos</b> antes de investires, sobre os riscos e a tua experiência (art. 21.º).',
      '<b>Simulação da capacidade de suportar perdas</b>, calculada em 10% do teu património líquido (art. 21.º, n.º 5).',
      '<b>Aviso e confirmação expressa</b> se quiseres pôr num projeto mais do que 1 000 € ou 5% do teu património líquido, consoante o valor mais elevado (art. 21.º, n.º 7).',
      '<b>Período de reflexão de 4 dias</b> depois de fazeres uma oferta, durante o qual podes desistir sem penalização nem justificação (art. 22.º).',
      '<b>Ficha de informação fundamental sobre o investimento</b>, com o promotor, os riscos, os custos e as condições, antes de investires (art. 23.º).']},
    {t:'note',id:'n1',x:'O regulamento fixa também um teto de 5 milhões de euros por promotor, em 12 meses, para ofertas feitas nestas plataformas. Acima disso aplicam-se as regras dos prospetos.'},
    {t:'note',id:'n2',pending:true,x:'O regulamento europeu não se aplica a empréstimos a consumidores (P2P ao consumo). As plataformas desse tipo seguem outras regras, ou nenhuma regra específica no país onde estão. Encontrámos esta exclusão só em fontes secundárias; confirma no artigo 1.º do regulamento e pergunta à plataforma que licença tem.'},
    {t:'p',id:'p5',x:'O que a lei <b>não</b> te dá: não há garantia de capital, não há Fundo de Garantia de Depósitos (isto não é um depósito) e o supervisor não avalia se o projeto é bom. A autorização quer dizer que a plataforma cumpre regras de informação e de organização, não que os empréstimos vão ser pagos.'},
    {t:'h',id:'h5',x:'Um caso real'},
    {t:'p',id:'p6',x:'Em 2019, no Reino Unido, a plataforma Lendy, que financiava promotores imobiliários, entrou em insolvência com grande parte dos empréstimos em atraso. Os investidores esperaram anos pela venda das garantias e recuperaram só uma parte. No mesmo ano, fora da UE e sem supervisão a sério, várias plataformas de empréstimos fecharam e desapareceram com o dinheiro. As lições repetem-se: taxas altas, garantias que demoram a executar e o risco da própria plataforma.'},
    {t:'h',id:'h6',x:'Perguntas a fazer antes de investir'},
    {t:'ul',id:'u3',x:[
      'A plataforma está autorizada ao abrigo do regulamento europeu? Por que supervisor? Está no registo da ESMA?',
      'Quem é o promotor, há quanto tempo existe e quanto deve?',
      'Que garantia existe e quem a executa se houver incumprimento?',
      'Qual é a taxa de incumprimento histórica da plataforma, por ano e por nota de risco?',
      'Que comissões pagas? Há mercado secundário?',
      'O que acontece aos empréstimos se a plataforma fechar?']},
    {t:'h',id:'h7',x:'Os erros que mais custam'},
    {t:'ul',id:'u4',x:[
      'Ler a taxa anunciada como o ganho garantido.',
      'Pôr muito dinheiro em poucos projetos.',
      'Usar dinheiro de que vais precisar antes do fim do prazo.',
      'Confiar em «garantias de recompra» de plataformas que não estão autorizadas na UE.',
      'Pôr aqui o fundo de emergência ou uma fatia grande da carteira. Isto é uma parte pequena e arriscada, nunca a base.']},
    {t:'h',id:'h8',x:'Em Portugal'},
    {t:'p',id:'p7',x:'Podes usar plataformas portuguesas e de outros países da UE autorizadas ao abrigo do regulamento. A CMVM supervisiona as que estão em Portugal, e a ESMA mantém um registo público de todos os prestadores autorizados na UE. Antes de abrir conta, confirma o nome exato da plataforma nesse registo. Os juros e ganhos destas plataformas têm de ser declarados no IRS.'},
    {t:'note',id:'n3',pending:true,x:'Não confirmámos em fonte oficial como são tributados os juros de financiamento colaborativo por empréstimo, nem se há retenção na fonte quando a plataforma é estrangeira. Pergunta à plataforma que documento fiscal emite e confirma no Portal das Finanças antes de entregar a declaração.'},
    {t:'h',id:'h9',x:'Em poucas palavras'},
    {t:'ul',id:'u5',x:[
      'No crowdfunding emprestas ou investes diretamente; o risco de não pagarem é teu.',
      'A taxa anunciada é o máximo, não o esperado: um só incumprimento pode apagar o ganho.',
      'Diversifica por muitos projetos e nunca uses dinheiro de que vais precisar.',
      'O regulamento europeu dá-te teste, aviso acima de 1 000 € ou 5% do património, 4 dias para desistir e ficha de informação.',
      'Não há Fundo de Garantia de Depósitos: confirma a autorização no registo da ESMA.']},
    {t:'fazve',id:'q1',ensina:['p2','c2','p3'],q:'Pões 5 000 € em 10 empréstimos de 500 € a 9%. Dois falham e recupera-se metade desses dois. Quanto perdes no ano, em €?',unit:'€',answer:-Math.round(_cf_res(2,0.5)),tol:.02,why:'8 × 500 × 1,09 = 4 360 €, mais 2 × 250 € = 500 €. Total 4 860 €: perdes 140 €.'},
    {t:'decide',id:'q2',ensina:['u2','p4'],label:'Decide',q:'Fizeste uma oferta num projeto ontem e mudaste de ideias. O que podes fazer, numa plataforma autorizada na UE?',o:['Nada: o dinheiro já está comprometido','Desistir sem penalização, porque estás dentro do período de reflexão de 4 dias','Pagar uma comissão de saída'],c:1,why:'O regulamento dá aos investidores não sofisticados 4 dias para desistir da oferta sem justificação nem penalização.'},
    {t:'erro',id:'q3',ensina:['p5','u1'],label:'Encontra o erro',q:'Uma destas frases sobre crowdfunding está errada. Qual?',o:['A taxa paga o risco de incumprimento','Uma plataforma autorizada pela CMVM garante que os projetos pagam','Pode não haver forma de sair antes do fim','A própria plataforma é um risco'],c:1,why:'A autorização é sobre regras de informação e organização. Não garante nada sobre os empréstimos.'},
    {t:'decide',id:'q4',ensina:['p3','u4'],label:'Decide',q:'Tens 20 000 € investidos em ETFs e queres experimentar crowdfunding. Qual é o plano mais sensato?',o:['Pôr 10 000 € no projeto com a taxa mais alta','Pôr uma parte pequena, repartida por muitos projetos, e tratar como dinheiro que pode não voltar','Pôr o fundo de emergência, porque rende mais do que um depósito'],c:1,why:'É um investimento de risco alto e sem liquidez: deve ser uma parte pequena, diversificada e com dinheiro de que não precisas.'}
  ], src:[_cf_ue,_cf_esma,_CMVM] }
);
